(window.GIM_TS=window.GIM_TS||{})["Bekhorot.4"]={"from":96,"a":[["\u0003ר' יוחנן אומר:\u0004 אם רוצה אתה לדעת כמה לתת לפדיון הבן, קח \u0003דינרא הדריינא טריינא שייפא\u0004 \u0005[דינר\u0006 זהב של הקיסר \u0005אדריאנוס\u0006 או של הקיסר \u0005טריינוס משופשף,\u0006 ישן\u0005]\u0006 \u0003דמזבנא\u0004 \u0005[שנמכר]\u0006 \u0003בעשרים וחמשה זוזי\u0004 \u0005[זוזים]\u0006 דינרים של כסף, \u0003דל מינייהו שתותא\u0004 \u0005[הורד מהם שישית],\u0006 \u0003והנך\u0004 \u0005[והאחרים]\u0006 שנותרו, הם חמישה סלעים שיש לתת \u0003לפדיון הבן,\u0004 עשרים דינרים (ארבעה דינרים לסלע). ומקשים: אם מורידים מעשרים וחמישה שישית אין מקבלים עשרים דינרים, אלא \u0003הני עשרין וחד נכי דנקא הוי\u0004 \u0005[אלה\u0006 הנותרים \u0005עשרים ואחד\u0006 דינרים \u0005פחות מעה,\u0006 שישית הדינר, \u0005הם]!\u0006","\u0003אלא, דל שתותא וזוזא\u0004 \u0005[הורד\u0006 מהם \u0005שישית, ו\u0006עוד \u0005זוז],\u0006 \u0003והנך\u0004 \u0005[והאחרים]\u0006 יש לתת \u0003לפדיון הבן.\u0004 ומקשים: \u0003אכתי\u0004 \u0005[עדיין]\u0006 אין החשבון מדוייק, שהרי \u0003עשרין נכי דנקא הוי\u0004 \u0005[עשרים\u0006 דינרים \u0005פחות מעה,\u0006 שישית הדינר, \u0005הם]!\u0006 \u0003אלא דל זוזא ושתותא\u0004 \u0005[הורד\u0006 מהם \u0005דינר,\u0006 ומהנותר, עשרים וארבעה, הורד \u0005שישית],\u0006 \u0003והנך\u0004 \u0005[והאחרים]\u0006 שנותרו הרי זה שיעור חמישה סלעים \u0003לפדיון הבן.\u0004 ומעירים: \u0003דהוי להו עשרין מתקלי במתקלי דינרא\u0004 \u0005[שהם\u0006 במשקל \u0005עשרים\u0006 דינרי זהב קטנים הקרויים \"מתקלים\"\u0005],\u0006 \u0003דאינון עשרין ותמניא זוזי ופלגי ופלגא דנקא\u0004 \u0005[שהם\u0006 שווים \u0005עשרים ושמונה דינרים וחצי\u0006 דינר \u0005וחצי מעה,\u0006 שישית הדינר\u0005]\u0006 בדינרי כסף ערביים.","\u0003אמר רבא: סילעים דאורייתא\u0004 \u0005[סלעים של תורה],\u0006 שקלים שניתנים לפדיון הבן — משקלם \u0003תלתא ותילתא הוי\u0004 \u0005[שלושה ושליש\u0006 דינרים \u0005הם],\u0006 כל אחד מהם, ולא ארבעה דינרים. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עשרים גרה השקל\"\u0004 (שמות ל, יג), \u0003ומתרגמינן\u0004 \u0005[ואנו מתרגמים]\u0006 \"עשרים גרה\" שבפסוק — \u0003\"עשרין מעין\"\u0004 \u0005[עשרים מעות].\u0006 \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003שש מעה כסף\u0004 הם \u0003דינר,\u0004 ונמצא שעשרים מעות, ששוות לסלע של תורה, שוות לשלושה דינר ושליש.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: נאמר בתורה כי המקדיש שדה בשנת היובל נותן בפדיונו (עבור ארבעים ותשע שנים) חמישים סלעים לכל שטח שזורעים בו כור שעורים. ומצד אחר אמרו חכמים שנותן סלע ופונדיון (חצי מעה) לשנה. ועל כך שואלים בבריתא: \u0003והלא\u0004 ב\u0003סלע של קדש\u0004 יש \u0003ארבעים ושמנה פונדיונין,\u0004 ואילו לדברי חכמים, פדיון ארבעים ותשע השנים עולה לארבעים ותשעה סלעים וארבעים ותשעה פונדיונים, כלומר, חמישים סלעים ופונדיון, פונדיון אחד יתר על מה שציותה התורה!","\u0003פונדיון זה מה טיבו\u0004 — הרי זה \u0003קילבון לפרוטרוט\u0004 \u0005[תוספת עבור פריטה\u0006 של הסלע לפונדיונים\u0005].\u0006 על כל פנים, מבואר בברייתא שבסלע של תורה יש ארבעים ושמונה פונדיונים, ששווים עשרים וארבע מעות. שלא כדברי רבא, שאמר שסלע של תורה שווה לעשרים מעות בלבד!","ומשיבים: הדין שבברייתא נאמר \u0003בתר דאוסיפו עילוייהו\u0004 \u0005[לאחר שהוסיפו\u0006 חכמים \u0005עליהם]\u0006 על המטבעות, ארבע מעות לסלע. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]: נאמר\u0006 \u0003\"עשרים גרה השקל\"\u0004 (ויקרא כז, כה) — \u0003למדנו\u0004 מכאן \u0003לשקל\u0004 שבתורה \u0003שהוא עשרים גרה, ומנין שאם רצה להוסיף\u0004 על מנין המעות שבשקל \u0003יוסיף? תלמוד לומר:\u0004 \"עשרים גרה \u0003יהיה\u0004 השקל\" (ויקרא כז, כה), לשון הויה, הוספה. \u0003יכול יפחות\u0004 מעשרים מעות בשקל? \u0003תלמוד לומר:\u0004 \"עשרים גרה \u0003הוא\"\u0004 (במדבר יח, טז), שלא יפחות ממנין זה.","מסופר, \u0003רב אשי שדר ליה שבסר זוזי\u0004 \u0005[שלח לו שבעה עשר זוזים]\u0006 \u0003לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא\u0004 שהיה כהן \u0003בפדיון הבן,\u0004 ועמם \u0003שלח ליה\u0004 \u0005[לו]\u0006 רב אשי דברים אלו: \u0003לישדר לי מר תלתא יתירתא דאיכא עלוייהו\u0004 \u0005[ישלח לי אדוני\u0006 בחזרה \u0005שליש דינר מיותר שיש עליהם],\u0006 מפני שלפי דברי רבא, שסלע של תורה שווה שלושה דינרים ושליש, נמצא שחמישה סלעים שווים ששה עשר ושני שליש דינר; ונמצא שבתוך שבעה עשר הדינרים ששלח לו יש שליש דינר מיותר! \u0003שלח ליה\u0004 \u0005[לו]\u0006 רב אחא בתשובה: \u0003לשדר לי מר תלתא אחרינא דאוסיפו עילוייהו\u0004 \u0005[שישלח לי אדוני שלושה דינרים אחרים שהוסיפו עליהם],\u0006 שהרי חכמים הוסיפו על הסלע של התורה, וחשבון חמישה סלעים עולה לפי זה לעשרים דינרים, שלושה דינרים יתרים על אלו שכבר שלח רב אשי.","ועוד בענייני שיעורי המטבעות, \u0003אמר ר' חנינא: כל\u0004 שקל \u0003כסף האמור בתורה סתם\u0004 — הרי הוא \u0003סלע\u0004 (שקל) אחד, וכל שקל כסף שנזכר ב\u0003נביאים\u0004 סתם — הרי הוא ב\u0003ליטרין\u0004 כסף במשקל של עשרים וחמישה סלעים, וכל שקל כסף שנזכר ב\u0003כתובין\u0004 סתם — הרי הוא ב\u0003קינטרין,\u0004 כסף במשקל של מאה סלעים. \u0003חוץ מן כספו של עפרון, שאף על פי שכתוב בתורה\u0004 \"שקל כסף\" \u0003סתם\u0004 הרי הוא ב\u0003קינטרין, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ארבע מאות שקל כסף עובר לסחר\"\u0004 (בראשית כג, טז), שפירושו: מטבע כסף שמתקבל בתורת שקל בכל מקום, \u0003ואיכא דוכתא דקא קרו לקינטרא \"תיקלא\"\u0004 \u0005[ו\u0006הרי \u0005יש מקום שקוראים\u0006 \u0005לקינטרא \"שקל\"].\u0006","בענין \"דינרא הדריינא טריינא שייפא\" שהזכיר ר' יוחנן בראש עמוד זה, מביאים מה ש\u0003אמר ר' אושעיא: ביקשו לגנוז כל כסף וזהב ש\u0004נמצא \u0003בעולם מפני כספה וזהבה של ירושלים\u0004 שהיה באוצר המקדש, ונטלוהו הגויים, \u0003עד שמצאו לו מקרא מן התורה שהוא מותר\u0004 — \u0003שנאמר: \"ובאו בה פריצים וחללוה\"\u0004 (יחזקאל ז, כב), ומכאן יש ללמוד כשבאים הפריצים ובוזזים את הכסף הרי הוא מתחלל, ואין חוששים לקדושה שבו.","ושואלים: \u0003וירושלים הויא רובא דעלמא\u0004 \u0005[היא רוב העולם]?\u0006 ומדוע יאסרו את כל הכסף והזהב שבעולם מפני המיעוט של ירושלים? \u0003אלא אמר אביי: בקשו לגנוז דינרא הדריינא טירייאנא שייאפא\u0004 \u0005[\u0006את מטבעות ה\u0005דינר\u0006 של הקיסר \u0005אדריינוס\u0006 או של הקיסר \u0005טריינוס המשופשפים,\u0006 הישנים\u0005],\u0006 \u0003מפני טבעה\u0004 (המטבע) \u0003של ירושלים,\u0004 מפני שבמטבעות אלו שנעשו בירושלים היה מעורב הרבה מאד מכסף המקדש, \u0003עד שמצאו לה מקרא מן התורה שהוא מותר, שנאמר: \"ובאו בה פריצים וחללוה\".\u0004"],["\u0003אמר רב יהודה אמר רב אסי: כל \"כסף\" האמור בתורה סתם,\u0004 ולא נאמר שהוא שקלים — הוא דינר \u0003כסף צורי,\u0004 וכל כסף האמור ב\u0003דבריהם\u0004 של חכמים — הוא \u0003כסף מדינה,\u0004 כלומר, דינר כסף פשוט, ששווה לשמינית דינר צורי.","ושואלים: \u0003וכללא\u0004 \u0005[\u0006והאם \u0005כלל]\u0006 \u0003הוא,\u0004 שכל כסף האמור בתורה סתם הוא דינר כסף צורי? \u0003והרי\u0004 דין זה של \u0003טענה,\u0004 שטוען אדם על חבירו שחייב לו דבר_מה, וחבירו מודה רק במקצת הטענה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי יתן איש אל רעהו כסף או כלים לשמור\u0004 וגונב מבית האיש...\" (שמות כב, ו), דין זה בא לפני הדיינים ומשביעים את הנתבע, שנאמר: \"...","עד האלהים יבא דבר שניהם\" (שמות כב, ח), ופירשו חכמים שהוא לשבועה, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003שבועת הדיינין\u0004 היא כאשר \u0003הטענה\u0004 (התביעה) היא על \u0003שתי\u0004 מעות \u0003כסף\u0004 לפחות, ששוות לשליש דינר. ונמצא ש\"כסף\" הוא פחות מדינר, שלא כדברי רב אסי!","ומשיבים: \u0003שאני התם דכתיב\u0004 \u0005[שונה שם,\u0006 לגבי טענה, \u0005שנאמר]:\u0006 \u0003\"כסף או כלים\",\u0004 ולמדים הכסף והכלים זה מזה: \u0003מה כלים\u0004 משמעם לפחות \u0003שנים\u0004 — \u0003אף כסף\u0004 הוא לפחות \u0003שנים. ומה כסף\u0004 משמעו \u0003דבר חשוב,\u0004 ואפילו מעה כסף חשובה — \u0003אף כלים דבר חשוב.\u0004 ואין להקשות משם לרב אסי, שמדבר ב\"כסף\" שנאמר בתורה לבדו.","ועוד מקשים: \u0003והרי\u0004 כסף שפודים בו \u0003מעשר\u0004 שני, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כב), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003הפורט\u0004 (מצרף פרוטות) ל\u0003סלע ממעות\u0004 שפדה בהן \u0003מעשר שני.\u0004 הרי ש\"כסף\" הוא גם מעות, ולא רק דינר! ומשיבים: \u0003\"כסף\" \"כסף\"\u0004 (דברים יד, כב) שנאמר במעשר שלוש פעמים (\"ונתתה בכסף\", \"וצרת הכסף\", \"ונתתה הכסף\". דברים כה—כו) \u0003ריבה\u0004 אפילו פרוטה.","ומקשים: \u0003והרי\u0004 פדיון \u0003הקדש, דכתיב\u0004 \u0005[שנאמר]\u0006 בו כסף: \u0003\"ונתן הכסף וקם לו\"\u0004 (ראה ויקרא כז, יט), \u0003ואמר שמואל: הקדש\u0004 אפילו \u0003שוה מנה\u0004 (מאה דינר) \u0003שחיללו על שוה פרוטה\u0004 מחולל, ולאו דווקא על דינר כסף, וקשה לרב אסי! ומשיבים: פדיון \u0003הקדש נמי\u0004 \u0005[גם כן],\u0006 \u0003יליף\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"קדש\" \"קדש\" ממעשר\u0004 שני (ראה דברים יד דברים ל), ש\"כסף\" שבו אינו דוקא דינר כסף, אלא אפילו פרוטה.","ומקשים: \u0003והרי קידושי אשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצאה חנם אין כסף\"\u0004 (שמות כא, יא), ותנן \u0005[ושנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים:\u0004 אישה מתקדשת \u0003בדינר ובשוה דינר\u0004 לכל הפחות, \u0003ובית הלל אומרים בפרוטה ובשוה פרוטה; לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 ש\u0003רב אסי\u0004 ש\u0003אמר:\u0004 כל \"כסף\" האמור בתורה הוא דינר כסף — \u0003כבית שמאי\u0004 הוא סבור? והלא אין חולק על כך שהלכה כבית הלל!","\u0003אלא, אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב יהודה אמר רב אסי: כל כסף קצוב האמור בתורה,\u0004 שנאמר בו סכום מסויים, כגון \"חמשים כסף\" באונס — הריהו \u0003כסף צורי,\u0004 וכל כסף \u0003של דבריהם\u0004 — הריהו \u0003כסף מדינה.\u0004","ומקשים: אם כן הוא \u0003מאי קמשמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בכך? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 את כל הדינים האלה במשנתנו: \u0003חמש סלעים של בן,\u0004 שלושים של עבד, חמישים של אונס ושל מפתה, ומאה של מוציא שם רע — כולם בשקל הקדש במנה צורי!","ומשיבים, מה שאמר: \u0003ושל דבריהם\u0004 — \u0003כסף מדינה איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר. ורב אסי מתייחס למה \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003התוקע\u0004 (הסוטר באוזן) \u0003לחבירו\u0004 בדרך בזיון — \u0003נותן לו\u0004 כקנס \u0003סלע,\u0004 שכך קבעו חכמים. וכך הוא אומר: \u0003ולא תימא\u0004 \u0005[ואל תאמר]\u0006 שנותן \u0003סלע\u0004 צורי שהוא שווה \u0003ארבע זוזי\u0004 \u0005[ארבעה זוזים,\u0006 דינרים\u0005],\u0006 \u0003אלא פלגא דזוזא\u0004 \u0005[חצי זוז,\u0006 דינר\u0005],\u0006 וכפי \u0003דקרי אינשי\u0004 \u0005[שקוראים אנשים]\u0006 \u0003\"סלע\"\u0004 למטבע \u0003פלגא דזוזא\u0004 \u0005[חצי זוז],\u0006 ולסלע זה התכוונה המשנה.","מסופר, \u0003חנן בישא תקע ליה לההוא גברא\u0004 \u0005[חנן הרע סטר באוזן לאדם אחד],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב הונא, אמר ליה\u0004 \u0005[לו]\u0006 לחנן: \u0003הב ליה פלגא דזוזא\u0004 \u0005[תן לו חצי זוז].\u0006 \u0003הוה ליה\u0004 \u0005[היה לו]\u0006"],["\u0003זוזא מאכא בהדיה דלא נפיק\u0004 \u0005[זוז מעוך איתו, שאינו יוצא],\u0006 לא רצה לקבל ממנו. \u0003תקע ליה אחרינא ויהביה ניהליה\u0004 \u0005[סטר לו\u0006 סטירה \u0005אחרת ונתן לו אותו]\u0006 את הזוז המעוך, עבור שתי הסטירות.","שנינו במשנתנו: \u0003שלשים של עבד, חמשים של אונס ושל מפתה,\u0004 ומאה של מוציא שם רע — כולם בשקל הקדש במנה צורי. ושואלים: \u0003הא תו\u0004 \u0005[זו עוד],\u0006 התוספת של \"כולם בשקל הקדש במנה צורי\" \u0003למה לי\u0004 לומר שנית? \u0003הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו בראש\u0006 המשנה\u0005]!\u0006","ומשיבים: \u0003אונס ומוציא שם רע איצטריך\u0004 \u0005[הוצרך\u0006 לחזור ולומר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון דלא כתיב בהו\u0004 \u0005[שלא נאמר בהם]\u0006 בתורה \u0003שקלים\u0004 במפורש, אלא רק \"כסף\" — \u0003אימא זוזי בעלמא\u0004 \u0005[אמור זוזים,\u0006 דינרים \u0005בלבד]\u0006 משלמים, ולא שקלים (השווים ארבעה דינרים), על כן \u0003קא משמע לן דמילף קא ילפי מהדדי\u0004 \u0005[משמיע לנו\u0006 התנא \u0005שהם למדים זה מזה],\u0006 ובכולם התשלום הוא בשקל הקודש.","שנינו במשנה: וכולם נפדים בכסף ובשווה כסף \u0003חוץ מן השקלים\u0004 שחייב לתת דוקא במטבע. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא: \u0003חוץ מן השקלים, ומעשר\u0004 שני, \u0003והראיון,\u0004 שתי מעות כסף שצריך כל אדם להביא למקדש כדי לקנות עולת ראיה ברגל, שדינם במטבע דווקא.","ומבארים: \u0003שקלים\u0004 לא מועיל בהם שווה כסף — כפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מצרפין\u0004 (מחליפים) בני העיר \u0003שקלים\u0004 שאספו \u0003לדרבונות\u0004 (מטבעות זהב גדולים), \u0003מפני משאוי הדרך\u0004 כדי שלא יכביד עליהם משקל מטבעות הכסף. ודוקא למטבעות מצרפים, ולא לדבר אחר שהוא שווה כסף.","\u0003מעשר\u0004 שני אינו נפדה בשווה כסף — כפי \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כה), ולמדים מלשון \"וצרת\" שצריך שיהיה כסף שטבעו בו צורה. \u0003והראיון\u0004 — הוא מה ש\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: שלא יביא סיגה,\u0004 גוש כסף מלא סיגים, \u0003לעזרה.\u0004","\u0003אין פודין\u0004 בכור, \u0003לא בעבדים, ולא בשטרות\u0004 חוב שיש לו על אחרים, \u0003ולא בקרקעות, ולא הקדשות.\u0004 אם האב \u0003כתב לכהן\u0004 שטר \u0003שהוא חייב ליתן\u0004 לו \u0003חמשה סלעים\u0004 לפדיון בנו — \u0003חייב ליתן לו\u0004 חמישה סלעים, \u0003ו\u0004אולם \u0003בנו אינו פדוי\u0004 בשטר זה, אלא צריך האב ליתן לו חמישה סלעים אחרים. \u0003לפיכך, אם רצה הכהן ליתן\u0004 להחזירם \u0003לו במתנה\u0004 — \u0003רשאי.\u0004","\u0003המפריש\u0004 חמישה סלעים ל\u0003פדיון בנו, ואבד\u0004 הכסף קודם שהגיע ליד הכהן — האב \u0003חייב באחריותו,\u0004 ולפיכך יביא לכהן כסף אחר לפדיון, \u0003שנאמר\u0004 לאהרן הכהן: \"כל פטר רחם... באדם ובבהמה יהיה לך אך פדה תפדה את בכור האדם...\" (במדבר יח, טו), \u0003\"יהיה לך\" ו\u0004אז \u0003\"פדה תפדה\",\u0004 שרק כאשר הכסף \"יהיה לך\", כלומר, לכהן — יהיה הבן פדוי.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבי, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: בכל פודין בכור אדם, חוץ מן השטרות.\u0004 ובמשנתנו נאמר שאין פודים גם בעבדים ובקרקעות. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 של \u0003ריבויי?\u0004","ואומרים: \u0003דריש ריבויי ומיעוטי\u0004 \u0005[דורש\u0006 הוא בדרך של \u0005ריבויים ומיעוטים],\u0006 כיצד? \u0003\"ופדויו מבן חדש תפדה\"\u0004 (במדבר יח, טז) — הרי זה \u0003ריבה,\u0004 מפני ש\"תפדה\" בסתם משמעו בכל דבר, \u0003\"בערכך כסף חמשת שקלים\"\u0004 — הרי זה \u0003מיעט,\u0004 דוקא בכסף, ומה שנאמר שוב \"פדה \u0003תפדה\u0004 את בכור האדם\" (במדבר יח, טו) — \u0003ריבה,\u0004 נמצא ש","\u0003ריבה ומיעט וריבה,\u0004 ובכך \u0003ריבה הכל,\u0004 חוץ מדבר אחד שנתמעט ממה שנאמר \"כסף\". \u0003מאי רבי\u0004 \u0005[מה ריבה]?\u0006 \u0003רבי כל מילי\u0004 \u0005[ריבה כל הדברים],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 בכך — \u0003מיעט שטרות,\u0004 מפני שהם הרחוקים ביותר מכסף, שהרי אין להם שווי עצמי, ואינם משמשים אלא לראיה או כדי לקנות בהם.","\u0003ורבנן דרשי\u0004 \u0005[דורשים]\u0006 בשיטת \u0003כלל ופרט: \"ופדויו מבן חדש\"\u0004 — הרי זה \u0003כלל, \"בערכך כסף חמשת שקלים\"\u0004 — \u0003פרט, \"תפדה\"\u0004 — \u0003חזר וכלל,\u0004","\u0003כלל ופרט וכלל אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט: מה הפרט מפורש\u0004 — \u0003דבר המטלטל וגופו\u0004 (הוא עצמו) שווה \u0003ממון, אף כל דבר המטלטל וגופו ממון\u0004 בכלל זה, \u0003יצאו קרקעות\u0004 שאין פודים בהם — מפני \u0003שאין\u0004 הם \u0003מטלטלין, יצאו עבדים\u0004 — מפני \u0003שהוקשו\u0004 (הושוו בכתוב) \u0003לקרקעות, יצאו שטרות שאף על פי ש\u0004הן \u0003מטלטלין\u0004 — \u0003אין גופן ממון,\u0004 ואינם משמשים אלא לראיה או כדי לקנות בהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר: ורבי, ריבויי ומיעוטי דריש\u0004 \u0005[ו\u0006בדרך של \u0005ריבויים ומיעוטים\u0006 הוא \u0005דורש]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבי כללי ופרטי דריש\u0004 \u0005[כללים ופרטים\u0006 הוא \u0005דורש]\u0006 \u0003ב\u0004ענין \u0003מרצע\u0004 שרוצעים בו את אוזן העבד, שנאמר בו: \"ולקחת את המרצע ונתתה באזנו ובדלת והיה לך עבד עולם...\" (דברים טו, יז).","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בענין זה: \u0003\"מרצע\"\u0004 — \u0003אין לי אלא מרצע\u0004 בלבד, \u0003מנין לרבות הסול\u0004 (עץ מחודד), \u0003והסירא\u0004 (קוץ), \u0003והמחט, והמקדח, והמכתב\u0004 (החרט שכותבים בו על שעוה)? \u0003תלמוד לומר: \"ולקחת\"\u0004 (דברים טו, יז) — הרי זה בא \u0003לרבות כל דבר שנלקח ביד,\u0004 אלו \u0003דברי ר' יוסי בר' יהודה. רבי אומר: מרצע\u0004 — \u0003מה מרצע מיוחד\u0004 שהוא כלי \u0003של מתכת, אף כל\u0004 כלי \u0003של מתכת\u0004 בכלל זה, אבל לא קוץ וכדומה.","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003רבי דריש כללי ופרטי\u0004 \u0005[דורש כללים ופרטים],\u0006 \"ולקחת\" — כלל, \"מרצע\" — פרט, \"ונתת באזנו\" — חזר וכלל; מה הפרט ידוע שהוא ממתכת — אף כל כלי של מתכת. \u0003ר' יוסי בר' יהודה דריש ריבויי ומיעוטי\u0004 \u0005[דורש ריבויים ומיעוטים]!\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003בעלמא\u0004 \u0005[ב\u0006דרך \u0005כלל]\u0006 \u0003רבי כללי ופרטי דריש\u0004 \u0005[כללים ופרטים\u0006 הוא \u0005דורש].\u0006 \u0003והכא\u0004 \u0005[וכאן],\u0006 לענין פדיון הבן, הוא דורש \u0003כ\u0004דברי \u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל.\u0004","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 בענייני סימני דגים טהורים: מה שנאמר \u0003\"במים\" \"במים\" שתי פעמים,\u0004 \"את זה תאכלו מכל אשר במים, כל אשר לו סנפיר וקשקשת במים...\", ואחריהם מופיע הפרט \"בימים ובנחלים\" (ויקרא יא, ט) — ד\u0003אין\u0004 לדרוש פסוק \u0003זה\u0004 בדרך לימוד של \u0003כלל ופרט,\u0004 \u0003אלא\u0004 בכל מקרה בו יש שני כללים סמוכים, ואחריהם בא פרט — יש לדון על כך בדרך \u0003ריבה ומיעט.\u0004 והוא הדין לענין פדיון הבן, שהואיל ומתחילה נאמרה פעמיים לשון כלל \"תפדה\" \"תפדה\", ואחר כך הפרט \"כסף\" — יש לדונו כריבוי ומיעוט, ולמעט רק שטרות.","\u0003ורבנן אמרי כדאמרינן במערבא\u0004 \u0005[וחכמים אומרים כמו שאומרים בארץ ישראל]:\u0006 \u0003כל מקום שאתה מוצא שתי כללות הסמוכים זה לזה\u0004 ואחריהם בא פרט — \u0003הטל\u0004 את ה\u0003פרט ביניהם, ודונם בכלל ופרט,\u0004 ומשום כך הם ממעטים גם קרקעות ועבדים.","שנינו במשנתנו: \u0003ולא בהקדשות.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאינו יכול לפדות בהם, שהרי \u0003לאו דידיה נינהו\u0004 \u0005[לא שלו הם]!\u0006 ומשיבים, \u0003אימא\u0004 \u0005[אמור]:\u0006"],["\u0003ולא הקדשות\u0004 נפדים \u0003בכל אלו\u0004 שהוזכרו תחלה, עבדים שטרות וקרקעות.","שנינו במשנתנו: \u0003כתב לכהן שהוא חייב לו חמשה סלעים חייב ליתן לו\u0004 ובנו אינו פדוי. \u0003אמר עולא: דבר תורה,\u0004 מדין תורה \u0003בנו פדוי\u0004 לכשיתן אותם חמישה סלעים. אם כן, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמרו חכמים ש\u0003אין בנו פדוי\u0004 עד שיתן לו חמישה סלעים אחרים? \u0003גזירה שמא יאמרו\u0004 אנשים ש\u0003פודין בשטר\u0004 בלבד, גם בלא לתת חמישה סלעים.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן\u0004 ברייתא: \u0003בנו פדוי לכשיתן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן:\u0004 ברייתא \u0003זו\u0004 היא מ\u0003דברי ר' יוסי בר' יהודה סתימתא\u0004 \u0005[\u0006שדבריו נאמרו \u0005בסתם],\u0006 בלא להזכיר את שמו. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003זו דברי ר' אלעזר בר' שמעון סתימתא\u0004 \u0005[בסתם],\u0006 \u0003אבל חכמים אומרים: אין בנו פדוי\u0004 לכשיתן. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003אין בנו פדוי.\u0004","שנינו במשנתנו: \u0003לפיכך אם רצה הכהן ליתן לו במתנה\u0004 — \u0003רשאי.\u0004 ואומרים: \u0003תנינא להא\u0004 \u0005[שנינו\u0006 בדין זה שבמשנתנו \u0005את זו]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003נתנו\u0004 את פדיון הבן \u0003לעשרה כהנים בבת אחת\u0004 — \u0003יצא, בזה אחר זה\u0004 — \u0003יצא. נטלו\u0004 הכהן את פדיון הבן \u0003והחזירו לו\u0004 — \u0003יצא.\u0004","\u0003וכך היה מנהגו של ר' טרפון\u0004 שהיה כהן, \u0003שהיה נוטל\u0004 את הפדיון \u0003ומחזיר\u0004 לאב. \u0003וכששמעו חכמים בדבר אמרו: קיים זה הלכה זו\u0004 ששנינו בברייתא זו. ותוהים: קיים \u0003הלכה זו ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003אלא,\u0004 הכוונה היא, \u0003קיים זה אף הלכה זו.\u0004","מסופר, \u0003ר' חנינא,\u0004 שהיה כהן, \u0003הוה\u0004 \u0005[היה]\u0006 \u0003רגיל\u0004 בכך, \u0003ו\u0004היה \u0003שקיל ומהדר\u0004 \u0005[לוקח ומחזיר]\u0006 את דמי הפדיון, פעם אחת \u0003חזייה לההוא גברא דהוה קא אזיל ואתי קמיה\u0004 \u0005[ראה אדם אחד\u0006 שנתן לו פדיון הבן \u0005שהיה הולך ובא לפניו],\u0006 כדי לזרז את ר' חנינא להחזיר לו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא גמרת ויהיבת\u0004 \u0005[הסכמת\u0006 בלבך \u0005ונתת],\u0006 \u0003מידעם ביש\u0004 \u0005[דבר רע\u0006 הוא\u0005],\u0006 \u0003הילכך\u0004 \u0005[על כן]\u0006 \u0003אין בנו פדוי.\u0004","שנינו במשנתנו: \u0003המפריש פדיון בנו ואבד\u0004 — \u0003חייב באחריותו.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר ר' שמעון בן לקיש: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"ערך\" \"ערך\" מערכין,\u0004 שנאמר בפדיון הבן: \"מבן חדש תפדה בערכך\" (במדבר יח, טז), ובערכין נאמר: \"ונתן את הערכך ביום ההוא\" (ויקרא כז, כג), וכשם שבערכין חייב באחריותם — כך בבכור חייב באחריות דמי הפדיון.","\u0003רב דימי אמר\u0004 בשם \u0003ר' יונתן:\u0004 נאמר בפדיון בכור \u0003\"וכל בכור בניך תפדה ולא יראו פני ריקם\"\u0004 (שמות לד, כ), \u0003ויליף\u0004 \u0005[ונלמד]\u0006 בגזירה שווה \u0003\"ריקם\" \"ריקם\" מעולת ראייה,\u0004 קרבן עולה שחייב כל עולה רגל להביא, שנאמר בה: \"ולא יראו פני ריקם\" (שמות כג, טו), \u0003מה עולת ראייה חייב באחריותו\u0004 של הקרבן — \u0003אף פדיון הבן חייב באחריותו.\u0004","על עיקר דיון הגמרא \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא:\u0004 והרי במשנתנו כבר מובא פסוק המחייב את האב באחריות על הפדיון, וכי צריך \u0003קרא לקרא\u0004 \u0005[מקרא\u0006 לסייע \u0005למקרא\u0006 אחר\u0005]?\u0006 \u0003אלא אמר רב פפא: הא\u0004 \u0005[זה]\u0006 דין משנתנו, שהאב חייב באחריות דמי הפדיון — \u0003כדקתני טעמא\u0004 \u0005[כמו ששנוי הטעם,\u0006 המקור לכך\u0005]\u0006 במשנה: \u0003\"יהיה לך... אך פדה תפדה\"\u0004 (במדבר יח, טו),","\u0003וכי איתמר\u0004 \u0005[וכאשר נאמרו]\u0006 דבריו של \u0003ריש לקיש\u0004 — \u0003ארישא איתמר\u0004 \u0005[על ראשה\u0006 של המשנה \u0005נאמר],\u0006 ששנינו בה: \u0003מת\u0004 בנו הבכור \u0003לאחר שלשים יום, אף על פי שלא נתן\u0004 לכהן חמישה סלעים — \u0003יתן.\u0004 ועל כך שאלו: \u0003מנא לן\u0004 \u0005[\u0006\u0005מנין לנו]\u0006 דבר זה? \u0003אמר ר' שמעון בן לקיש: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"ערך\" \"ערך\" מערכין,\u0004 וכשם שאם אמר המעריך \"ערך פלוני עלי\", ומת אותו פלוני, חייב המעריך לשלם, כך לגבי פדיון הבן, למרות שמת הבכור — חייב אביו לשלם.","\u0003רב דימי אמר\u0004 בשם \u0003ר' יונתן:\u0004 נאמר בפדיון הבן \u0003\"וכל בכור בניך תפדה ולא יראו פני ריקם\",\u0004 וגם בעולת ראיה נאמר: \"ולא יראו פני ריקם\", \u0003מה להלן\u0004 בעולת ראיה, אם מת — \u0003יורשין חייבין\u0004 להביא עולתו, \u0003אף כאן\u0004 בפדיון הבן, אם כבר נתחייב האב בפדיון בנו, ומת — \u0003יורשין חייבין\u0004 לתת חמישה סלעים לכהן.","\u0003הבכור\u0004 לאב \u0003נוטל פי שנים בנכסי האב, ואינו נוטל פי שנים בנכסי האם, ואינו נוטל בשבח\u0004 במה שהשביחו להנכסים לאחר מותו של האב, \u0003ולא\u0004 נוטל פי שנים \u0003בראוי,\u0004 במה שראוי לבוא לאב בירושה, ועדיין לא הגיע אליו, \u0003כ\u0004פי שהוא נוטל פי שנים \u0003ב\u0004מה שכבר היה \u0003מוחזק\u0004 ביד האב."],["\u0003ולא האשה\u0004 נוטלת את אלה מנכסי בעלה \u0003ב\u0004שביל חוב \u0003כתובתה,\u0004 כשנתגרשה או כשמת בעלה, \u0003ולא הבנות\u0004 נוטלות מהם \u0003ב\u0004שביל \u0003מזונותיהן\u0004 שהן זכאיות להם מנכסי אביהם שמת, \u0003ולא היבם\u0004 שייבם את אשת אחיו, וזוכה בחלק האח בירושה, נוטל את חלק אחיו בשבח ששבחו הנכסים לאחר מות האב, ולא בראוי להגיע לו. \u0003וכולם אין נוטלין בשבח, ולא\u0004 נוטלים \u0003בראוי כבמוחזק.\u0004","שנינו במשנה שהבכור אינו נוטל פי שנים בנכסי האם. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולו משפט הבכורה\"\u0004 (דברים כא, יז), לומר: \u0003משפט הבכורה\u0004 הוא \u0003לאיש, ואין משפט הבכורה לאשה,\u0004 שלגבי ירושת האשה אין משפט הבכורה נוהג.","ועוד שנינו לגבי הבכור: \u0003ואינו נוטל\u0004 פי שנים \u0003בשבח\u0004 שהשביחו נכסי האב לאחר מותו. וטעם הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כי את הבכור וכו' יכיר לתת לו פי שנים \u0003בכל אשר ימצא לו\"\u0004 (דברים כא, יז), והרי זה לא מצוי בידי האב בשעת מותו. ועוד שנינו: \u0003ולא\u0004 נוטל הבכור פי שנים \u0003בראוי כבמוחזק.\u0004 וגם בזה טעם הדבר — משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בכל אשר ימצא לו\",\u0004 וזה אינו מצוי בידו.","ועוד שנינו: \u0003ולא האשה\u0004 גובה את השבח, ולא את הראוי \u0003בכתובתה.\u0004 ותוהים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: בעל חוב גובה את השבח\u0004 מנכסי הלווה שהשביחו לאחר מותו. והרי כתובת האשה היא שטר חוב והרי היא כבעל חוב! \u0003אמר ר' אבא: מקולי כתובה שנו כאן,\u0004 זוהי הקלה מיוחדת שהקלו על הגברים בענייני כתובה.","ועוד שנינו: \u0003ולא הבנות\u0004 נוטלות \u0003ב\u0004שביל \u0003מזונותיהן,\u0004 בשבח ששבחו נכסי האב לאחר מותו, ולא בראוי. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מזון הבנות הוא מתנאי כתובה, ו\u0003תנאי כתובה ככתובה דמי\u0004 \u0005[נחשב],\u0006 ואינו גובה יותר מן הכתובה עצמה.","ועוד שנינו: \u0003ולא היבם\u0004 נוטל בשבח ובראוי. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"בכור\" קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 את היבם, ולכן דינו בחלק אחיו המת כדין בכור בחלק הבכורה. \u0003אמר אביי: לא שנו\u0004 דבר זה \u0003אלא בשבח ששבחו נכסים בין מיתה\u0004 של האח \u0003ליבום, אבל\u0004 מה ששבחו הנכסים \u0003בין יבום לחלוקה\u0004 של הנכסים — \u0003שקיל\u0004 \u0005[נוטל\u0006 בהם\u0005]\u0006 את חלק האח. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"יקום על שם אחיו המת\"\u0004 (דברים כה, ו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והרי קם\u0004 כבר.","\u0003רבא אמר: אפילו\u0004 שבח שהשביחו הנכסים \u0003בין יבום לחלוקה נמי לא שקיל\u0004 \u0005[גם כן אינו נוטל].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שהרי דינו \u0003כבכור, מה בכור אין לו\u0004 זכות יתירה \u0003קודם חלוקה,\u0004 \u0003אף יבם נמי\u0004 \u0005[גם כן]\u0006 \u0003אין לו קודם חלוקה.\u0004","שנינו במשנה: \u0003וכולם אין נוטלין בשבח.\u0004"],["ומבארים שהלכה זו חוזרת ונשנית \u0003לאיתויי שבחא דממילא\u0004 \u0005[להביא שבח ש\u0006בא \u0005מעצמו],\u0006 לאחר מות האב או הבעל, כגון שהיתה \u0003חפורה והוו שובלי\u0004 \u0005[שחת,\u0006 תבואה לא בשלה, בזמן שמת האב, \u0005ונעשתה שיבולים],\u0006 או \u0003שלפופי והוו תמרי\u0004 \u0005[פרחי הדקל ונעשו תמרים],\u0006 לומר שלמרות שהנכסים השביחו מעצמם ושאר האחים לא טרחו בדבר — אין גובים מהשבח. ומה ששנינו שוב: \u0003ו\u0004כולם \u0003לא\u0004 נוטלים \u0003בראוי כבמוחזק,\u0004 בא \u0003לאיתויי נכסי דאבי אבא\u0004 \u0005[להביא נכסים של אבי האב]\u0006 כשמת האב קודם לאביו, לומר שהבכור אינו נוטל בהם פי שנים (וכן האשה אינה נוטלת בכתובתה, והבנות במזונותיהן, והיבם), למרות שנכסים אלו עתידים בודאות ליפול לידי הבנים, מפני שגם נכסים אלו נחשבים \"ראוי\", ולא מוחזק.","","\u0003ואלו\u0004 נכסים \u0003שאין חוזרין ביובל\u0004 כמו המוכר את שדהו שחוזר אליו ביובל: חלק \u0003הבכורה,\u0004 שאינו חוזר ומתחלק בין האחים ביובל, \u0003והיורש את אשתו,\u0004 שאינו מחזיר את הקרקע למשפחתה, \u0003והמייבם את אשת אחיו,\u0004 וזכה בחלקו בנכסי האב — אין חלק זה חוזר ומתחלק בין האחים,","\u0003והמתנה\u0004 שקיבל אדם שדה מחבירו — אלו \u0003דברי ר' מאיר. וחכמים אומרים: המתנה\u0004 דינה \u0003כמכר,\u0004 וחוזרת ביובל. \u0003ר' אלעזר אומר: כולם חוזרין ביובל. ר' יוחנן בן ברוקה אומר: היורש את אשתו יחזיר\u0004 את הקרקע \u0003לבני משפחה,\u0004 כלומר, למשפחת אביה, \u0003וינכה מהן את הדמים,\u0004 דמי הקרקע.","שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר\u0004 שכל אלו חוזרים ביובל? ומשיבים: \u0003מכר הוא דאמר רחמנא ליהדר\u0004 \u0005[שאמרה התורה שיחזור]\u0006 \u0003ביובל\u0004 (ויקרא כה, כז), אבל \u0003מתנה וירושה לא\u0004 חוזרים, \u0003והני\u0004 \u0005[ואותם]\u0006 שבמשנתנו הלמדים \u0003מירושה\u0004 דינם כ\u0003ירושה,\u0004 ואותם שבמשנתנו הלמדים מ\u0003מתנה\u0004 דינם כ\u0003מתנה.\u0004 ומבארים: ב\u0003בכור\u0004 נאמר \u0003\"לתת לו פי שנים\"\u0004 (דברים כא, יז), ואם כן, \u0003מתנה קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 לחלק הבכורה,","\u0003והיורש את אשתו\u0004 אינו מחזיר ביובל, מפני שר' מאיר סבור ש\u0003ירושת הבעל דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005],\u0006 וירושה אינה חוזרת, \u0003והמייבם את אשת אחיו\u0004 אינו מחזיר — מפני ש\u0003\"בכור\" קרייה רחמנא\u0004 \u0005[קראה לו התורה]\u0006 ליבם, ור' מאיר לשיטתו, שחלק הבכורה אינו חוזר ביובל.","ועוד שנינו במשנה: \u0003וחכמים אומרים מתנה כמכר,\u0004 וחוזרת ביובל. ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 שהם חולקים על ר' מאיר דוקא בענין מתנה? ומשיבים: המלה \u0003\"תשבו\"\u0004 (בשנת היובל הזאת תשבו איש אל אחזתו\", ויקרא כה, יג) מיותרת, שהרי כבר נאמר מתחילה: \"...יובל הוא תהיה לכם ושבתם איש אל אחזתו\" (ויקרא כה, י); והם סבורים שהיא באה \u0003לרבות את המתנה\u0004 שחוזרת ביובל.","\u0003והני\u0004 \u0005[ואלה]\u0006 האחרים שבמשנתנו \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003ירושה נינהו\u0004 \u0005[הם],\u0006 ולכן אינם חוזרים ביובל; לגבי ירושת הבעל — סבורים חכמים שהיא מן התורה; ובמה שנוטל היבם הוא נחשב כבכור, וב","\u0003בכור אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"לתת לו פי שנים\".\u0004 וחכמים חולקים על ר' מאיר הלמד מכתוב זה כי יש לבכורה דין מתנה, אלא לדעתם \u0003מקיש\u0004 (משווה) הכתוב \u0003חלק בכורה לחלק\u0004 שנוטל הבכור כאח \u0003פשוט, מה חלק פשוט\u0004 הוא \u0003ירושה,\u0004 ואינו חוזר ומתחלק בין האחים ביובל, אלא מה שקיבל כל אח הוא נחלתו, שנאמר: \"ביום הנחילו את בניו\" (דברים כא, טז), \u0003אף חלק בכורה\u0004 הוא \u0003ירושה,\u0004 ואינו חוזר ביובל. ועוד שנינו במשנתנו: \u0003ר' אלעזר אומר: כולם חוזרים ביובל.\u0004 ומבארים: \u0003סבר לה כרבנן\u0004 \u0005[סבור הוא\u0006 כשיטת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003\"תשבו\"\u0004 — \u0003לרבות את המתנה\u0004 שחוזרת ביובל, \u0003והני כולהו\u0004 \u0005[ואלה כולם]\u0006 שבמשנתנו, \u0003מתנה נינהו\u0004 \u0005[הם].\u0006 ומבארים: ב\u0003בכור\u0004 נאמר \u0003\"לתת לו פי שנים\",\u0004 הרי ש\u0003מתנה קרייה רחמנא\u0004 \u0005[קראה לו התורה]\u0006 לחלק הבכורה, \u0003ו\u0004בדין \u0003היורש את אשתו\u0004 סבור ר' אלעזר ש\u0003ירושת הבעל דרבנן\u0004 \u0005[מדברי חכמים]\u0006 היא, ואין דינה כירושה שאינה חוזרת ביובל. \u0003והמייבם את אשת אחיו,\u0004 חלק אחיו חוזר ביובל, שהרי \"בכור\" קרייה רחמנא \u0005[קראה אותו התורה],\u0006 ולשיטתו חלק הבכורה חוזר ביובל. \u0003אמר\u0004 \u0003ר' אסי אמר ר' יוחנן: האחין שחלקו\u0004 ביניהם את נכסי האב — אין אומרים שהוברר הדבר שהגיע כל אחד לנחלתו, אלא כ\u0003לקוחות הן,\u0004 שקנו זה מזה את חלקו, \u0003ומחזירין זה לזה ביובל\u0004 את החלקים שקיבלו. \u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב הושעיא\u0004 ממשנתנו: \u0003ואלו שאין חוזרין ביובל\u0004 — \u0003הבכורה!\u0004","","","","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין חוזרין\"\u0004 — \u0003אין חוזרין לבטלה,\u0004 שאין הבכור מפסיד את הבכורה, אלא לאחר שיחזרו ויחלקו ביניהם את הנכסים — יטול פי שנים. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: מכלל\u0004 הדברים עולה \u0003דמאן דאמר\u0004 \u0005[שמי שאומר]\u0006 במשנתנו ש\u0003חוזרין\u0004 — \u0003חוזרין לבטלה קאמר\u0004 \u0005[הוא אומר],\u0006 שהבכור שוב אינו נוטל פי שנים? ומדוע יפסיד את בכורתו?","\u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב חמא עליה\u0004 \u0005[עליו]\u0006 על \u0003רב ששת\u0004 פסוק זה: \u0003\"טובה חכמה עם נחלה\"\u0004 (קהלת ז, יא), שלא די להיות בעל נחלת ברייתות, כרב ששת, שהיה בקיא בברייתות, אלא נצרכת גם בקיאות בדברי החכמה של האמוראים; \u0003ולא שמיע להו הא\u0004 \u0005[ולא שמעו\u0006 דבר \u0005זה]\u0006 \u0003דכי אתי\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין אמר\u0004 בשם \u0003ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' אלעזר אמר\u0004 הלכה זו, \u0003משום\u0004 (בשם) \u0003ר' אלעזר בן שמוע\u0004 (שהוא התנא ר' אלעזר במשנתנו): \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חוזרין\u0004 ביובל — \u0003חוזרין לבטלה,\u0004 ויפסידו מה שקיבלו. שנינו במשנתנו, \u0003ר' יוחנן בן ברוקה אומר: היורש את אשתו יחזיר לבני\u0004 המשפחה וינכה מהן את הדמים. ושואלים: \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003ירושת הבעל דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחזיר לבני משפחה? ואי קסבר\u0004 \u0005[ואם סבור\u0006 הוא\u0005]\u0006 ש\u0003ירושת הבעל דרבנן\u0004 \u0005[מדברי חכמים],\u0006 אם כן ה\u0003דמים\u0004 שנוטל מבני משפחת אשתו \u0003מאי עבידתייהו\u0004 \u0005[מה מעשיהם],\u0006 מדוע לא יחזיר בחינם?","","ומשיבים: \u0003לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003ירושת הבעל\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ומעיקר הדין אינו צריך להחזיר. \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003כגון שהורישתו אשתו בית הקברות\u0004 של משפחתה, \u0003ומשום פגם משפחה,\u0004 שלא יהיו קבורים בנחלה השייכת לאדם זר, \u0003אמור רבנן\u0004 \u0005[אמרו חכמים]:\u0006 \u0003לשקול דמי וליהדר\u0004 \u0005[שיקח מעות ויחזיר\u0006 להם אותה הקרקע\u0005].\u0006","\u0003וכדתניא\u0004 \u0005[וכמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר קברו\u0004 או את ה\u0003דרך\u0004 ל\u0003קברו,\u0004 או את \u0003מקום מעמדו,\u0004 שמתקבצים שם אנשים כדי לקונן ולנחם את האבלים לאחר הקבורה, או את \u0003בית הספדו\u0004 — \u0003באים בני משפחה וקוברים אותו,\u0004 את המוכר, בקבר המשפחה, \u0003בעל כרחו\u0004 של הקונה, ונותנים לו את דמי הקבר או דרך הקבר, \u0003משום\u0004 שיש בזה \u0003פגם משפחה. ו\u0004לפי זה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ינכה להם מן הדמים\"\u0004 שבמשנתנו? לא הדמים שנוטל מן המשפחה, אלא שינכה מהדמים שמקבל מהם את \u0003דמי קבר אשתו,\u0004",""],["\u0003מעשר בהמה נוהג בארץ ובחוצה לארץ,\u0004 ונוהג \u0003בפני הבית\u0004 (בזמן שבית המקדש קיים), \u0003ושלא בפני הבית, בחולין אבל לא במוקדשים; ונוהג בבקר ובצאן, ואין מתעשרין מזה על זה,\u0004 אין מפרישים מעשר מן הבקר על הצאן ולהיפך, ונוהג \u0003בכבשים ובעזים ומתעשרין מזה על זה.\u0004","ונוהג \u0003בחדש ובישן,\u0004 בולדות שנולדו בשנים שונות, \u0003ואינן מתעשרין מזה על זה. שהיה בדין\u0004 (מן הסברה) לומר: \u0003ומה אם החדש והישן שאינן כלאים זה בזה,\u0004 שמין אחד הם — בכל זאת \u0003אינם מתעשרין מזה על זה, כבשים ועזים שהן\u0004 \u0003כלאים זה בזה\u0004 — \u0003אינו דין שלא יהו מתעשרין מזה על זה? תלמוד לומר: \"וצאן\"\u0004 (\"וכל מעשר בקר וצאן כל אשר יעבר תחת השבט העשירי יהיה קדש לה' \", ויקרא כז, לב), \u0003משמע\u0004 מכך ש\u0003כל \"צאן\"\u0004 הריהו מין \u0003אחד\u0004 לענין מצות מעשר בהמה, ומתעשרים מזה על זה.","על מה ששנינו שמעשר בהמה נוהג בחוצה לארץ, שואלים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005משנתנו]\u0006 היא ש\u0003לא כ\u0004דעת \u0003ר' עקיבא? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: יכול יעלה אדם\u0004 לירושלים \u0003מעשר בהמה מחוצה לארץ ויקריבנו\u0004 במקדש? \u0003תלמוד לומר: \"והבאתם שמה עלתיכם וזבחיכם ואת מעשרתיכם\"\u0004 (דברים יב, ו), ומלשון רבים של \"מעשרותיכם\" יש לדייק כי","\u0003בשתי מעשרות\u0004 שונים \u0003הכתוב מדבר, אחד מעשר בהמה ואחד מעשר\u0004 שני של \u0003דגן,\u0004 שאת שניהם יש להעלות למקום המקדש ולאוכלם, והכתוב מקישם זה לזה, ולפיכך: \u0003ממקום שאתה מעלה מעשר דגן,\u0004 כלומר, מארץ ישראל, שרק שם יש חיוב מעשר — משם \u0003אתה מעלה\u0004 גם \u0003מעשר בהמה, וממקום שאי אתה מעלה מעשר דגן,\u0004 מחוצה לארץ — \u0003אי\u0004 (אין) \u0003אתה מעלה\u0004 גם \u0003מעשר בהמה.\u0004 והרי במשנתנו נאמר שהוא נוהג בחוצה לארץ!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כדעת \u0003ר' עקיבא,\u0004 יש לחלק: \u0003כאן\u0004 בברייתא, הכוונה היא שאין מעלים אותו לירושלים כדי \u0003ליקרב\u0004 על המזבח, \u0003כאן\u0004 במשנתנו, ששנינו שהוא נוהג בחוצה לארץ, הרי זה \u0003ליקדש,\u0004 שצריך לעשר את הבהמות, ולקדש את העשירי. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 הדבר מדברי ר' עקיבא, \u0003דקא נסיב לה תלמודא\u0004 \u0005[שמביא את הלימוד]\u0006 ממה שנאמר \u0003\"והבאתם שמה\", שמע מינה\u0004 \u0005[למד מכאן],\u0006 שהוא ממעט את חוץ לארץ רק מחובת הבאתו לירושלים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאחר שאינו קרב, אמאי\u0004 \u0005[על מה,\u0006 לאיזה ענין\u0005]\u0006 הוא \u0003קדוש?\u0004 ומשיבים: \u0003ל\u0004היות \u0003נאכל במומו לבעלים,\u0004 שבעליו רשאים לאוכלו רק לכשיפול בו מום.","שנינו במשנתנו שמעשר בהמה נוהג \u0003בפני הבית ושלא בפני הבית.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו האידנא נמי\u0004 \u0005[בזמן הזה גם כן]\u0006 יהיה נוהג, ומדוע אין אנו נוהגים במעשר בהמה? ומשיבים: הטעם הוא \u0003כ\u0004דברי רב הונא, ש\u0003אמר\u0004 \u0003רב הונא\u0004 בענין אחר: \u0003גזירה\u0004 היא שגזרו חכמים \u0003משום יתום\u0004 (ולד שמתה אמו קודם שנולד), שמא יכניסו אותו עם שאר הבהמות להתעשר, למרות שאינו חייב במעשר בהמה. ואף כאן, אחר חורבן הבית, חששו חכמים שמא יעשרו בשוגג גם את היתום.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מעיקרא נמי\u0004 \u0005[מתחילה גם כן],\u0006 בזמן הבית, \u0003לא\u0004 יפרישו מעשר בהמה, גזירה שמא יפרישו גם מן היתום! \u0003אלא,\u0004 מדוע לא חששו לכך — מפני ש\u0003אפשר בהכרזה\u0004 שיכריזו שיתום פטור ממעשר בהמה. אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 אחר החורבן — \u0003אפשר בהכרזה!\u0004","\u0003אלא אמר רבה:\u0004 הטעם הוא \u0003משום תקלה,\u0004 שהואיל ואין מקריבים בזמן הזה, והמעשר נשאר בבית בעליו — עלול הוא לבוא לידי תקלה, לשוחטו ולאוכלו קודם שיפול בו מום. ומוסיפים: \u0003ומנא תימרא דחיישינן\u0004 \u0005[ומנין אתה אומר שחוששים אנו]\u0006 \u0003לתקלה\u0004 אחר החורבן — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מקדישין ואין מעריכין\u0004 (נודרים ערכו של אדם להקדש), \u0003ואין מחרימין\u0004 \u0003בזמן הזה,\u0004 מחשש שמא תיגרם תקלה של מעילה בהקדש,","\u0003ואם הקדיש\u0004 או \u0003העריך\u0004 או \u0003החרים\u0004 בזמן הזה, \u0003בהמה\u0004 — \u0003תיעקר, פירות כסות וכלים\u0004 — יניחם ש\u0003ירקבו, מעות וכלי מתכות\u0004 — \u0003יוליך לים המלח\u0004 ושם יתאכלו. \u0003ואיזהו עיקור\u0004 בבהמה? \u0003נועל דלת בפניה והיא מתה מאיליה\u0004 ברעב.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאחר החורבן חוששים דלתקלה, \u0003בכור נמי לא ליקדש\u0004 \u0005[גם כן לא יתקדש]!\u0006 ומשיבים: וכי \u0003בכור בדידן תליא מילתא\u0004 \u0005[בנו תלוי הדבר]\u0006 להקדישו? והרי \u0003ב\u0004יציאתו מה \u0003רחם קדוש\u0004 מעצמו! ומשיבים: לא זו היתה השאלה, אלא \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 אם אתה חושש לתקלה, \u0003ליקנינהו לאודנייהו\u0004 \u0005[שיקנה את אוזניהם]\u0006 של המבכירות או של העוברים לפני לידתם, \u0003לגוים,\u0004 כדי ש\u0003לא ליקדש מעיקרא\u0004 \u0005[שלא יתקדש\u0006 הבכור בהם \u0005מתחילה],\u0006 בגלל שותפות הגוי, ולא יבואו בהם לידי תקלה!"],["ומשיבים: החושש לתקלה בבכור \u0003אפשר\u0004 לו שיעשה \u0003כ\u0004דברי \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: מותר לו לאדם להטיל מום בבכור קודם שיצא לאויר העולם.\u0004 ושואלים: לפי זה, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 במעשר, \u0003אפשר\u0004 לו \u0003דשדי ביה מומא מעיקרא\u0004 \u0005[שיטיל בו מום מתחילה],\u0006 קודם שיעשר, וכך יימנע מתקלה!","ומשיבים: \u0003מי ידע הי נפיק\u0004 \u0005[האם הוא יודע איזה מהם יוצא]\u0006 העשירי, שיטיל בו מום מתחילה? \u0003וכי תימא דמפיק ליה בריש עשרה\u0004 \u0005[ואם תאמר שיוציא אותו,\u0006 את בעל המום, \u0005בעשירי]\u0006 — \u0003\"לא יבקר בין טוב לרע\"\u0004 (ויקרא כז, יג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 בענין מעשר, שמשמעו שלא יבחר את העשירי, אלא כל העובר מעצמו עשירי תחת השבט הוא המקודש!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אפשר דשדי ביה מומא בכולי עדריה\u0004 \u0005[שיטיל מום בכל עדרו],\u0006 וממילא העשירי יהיה בעל מום — גם דבר זה אין לתקן, מפני ש\u0003מהרה יבנה בית המקדש, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 \u0003בהמה להקרבה וליכא\u0004 \u0005[ואין],\u0006 מפני שכל בהמות ישראל תהיינה בעלות מום.","ושואלים: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003בבכור בהמה,\u0004 כיצד אמר רב יהודה שמותר להטיל מום בכל בכור? והרי \u0003מהרה יבנה בית המקדש, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 \u0003בהמה להקרבה וליכא\u0004 \u0005[ואין]!\u0006 ומשיבים: לא יחסרו קרבנות על המזבח, מפני ש\u0003אפשר\u0004 להביא קרבנות מ\u0003פשוטין\u0004 (בהמות שאינן בכורות).","ושואלים: \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 במעשר בהמה, אין לחשוש שלא יהיו בהמות להקרבה, שהרי \u0003אפשר בלקוחין\u0004 (קנויים), בהמות שקנה מאחר, שהם פטורים ממעשר! ומשיבים: \u0003כיון דאיהו שדי ביה מומא בכולי עדריה\u0004 \u0005[שהוא,\u0006 כל מי שיש לו בהמות, \u0005מטיל מום בכל עדרו],\u0006 כדי להימנע מתקלה, \u0003ו\u0004מצד אחר, גם \u0003שכיחי מומי דפסילי\u0004 \u0005[שכיחים המומים שפוסלים]\u0006 \u0003בקדשים,\u0004 שהרי \u0003אפילו דוקין\u0004 (קרומים, כתמים) \u0003שבעין נמי פסלי\u0004 \u0005[גם כן פוסלים]\u0006 מהקרבה — \u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 מספיק בהמות להקרבה מן הקנויים. ולכן תיקנו חכמים שלא יעשרו כלל בהמות בזמן הזה.","שנינו במשנה שמעשר בהמה נוהג \u0003בחולין אבל לא במוקדשין.\u0004 ושואלים: \u0003מוקדשין\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, הלא \u0003לאו דידיה נינהו\u0004 \u0005[לא שלו הם]\u0006 כדי שיוכל להקדישם!","ומשיבים: מדובר כאן \u0003בקדשים קלים\u0004 כגון בהמות שלמים, \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יוסי הגלילי,\u0004 ש\u0003אמר: קדשים קלים\u0004 — \u0003ממון בעלים הם. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בדין הגוזל את חבירו, ונשבע על כך לשקר, שמה שנאמר בענין זה: \u0003\"ומעלה מעל בה' \"\u0004— הרי זה בא \u0003לרבות\u0004 הנשבע על \u0003קדשים קלים\u0004 שהקדיש חבירו, \u0003שהן\u0004 אמנם קרבן לה', ואולם הם \u0003ממון בעלים,\u0004 אלו \u0003דברי ר' יוסי הגלילי.\u0004 ואם כן, הואיל ולדעתו הם ממון בעלים \u0003סלקא דעתך אמינא ליעשרו\u0004 \u0005[יעלה על דעתך לומר שיתעשרו]\u0006 עם שאר בהמותיו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 במשנתנו שלא.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן],\u0006 שיתעשרו! ומשיבים: \"העשירי \u0003יהיה קדש\"\u0004 (ויקרא כז, לב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 בלשון עתיד, \u0003ולא\u0004 זה \u0003שכבר קדוש.\u0004","ותמהים: לפי הסבר זה נמצא כי \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דוקא משום \u0005שכתבה התורה]\u0006 \u0003\"יהיה קדש\",\u0004 אין דין מעשר בקדשים קלים, \u0003הא לאו הכי הוה אמינא\u0004 \u0005[הרי אם לא כך, הייתי אומר]\u0006 \u0003חיילא\u0004 \u0005[חלה]\u0006 \u0003קדושת מעשר עילויהו\u0004 \u0005[עליהם],\u0006 על קדשים קלים? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003קדושה חמורה\u0004 על \u0003קדושה קלה לא חיילא\u0004 \u0005[אינה חלה],\u0006 \u0003קדושה קלה\u0004 על \u0003קדושה קלה מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שלא חלה?","ומבארים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה הלכה שאנו רומזים לה — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אחד קדשי מזבח ואחד קדשי בדק הבית,\u0004 שהוקדשו לצרכי המקדש — \u0003אין משנין אותם מקדושה לקדושה,\u0004 ואין קדושת המזבח חלה על בהמה שהוקדשה לבדק הבית, למרות שהיא קלה יותר. \u0003אבל מקדישין אותו,\u0004 מקדיש אדם את הקרבן שלו \u0003הקדש עילוי\u0004 לבדק הבית, כלומר, שיתן להקדש בדק הבית את שווי טובת ההנאה שיש לו בקרבנו, וכן \u0003מחרימין אותו,\u0004 את הקרבן באופן זה לטובת הכהנים, שהחרמים שלהם. הרי שקדושת המזבח אינה חלה על קדושת בדק הבית שהיא קלה ממנה, ואם כן לא ייתכן שתחול קדושת מעשר בהמה על קדושת קרבן אחר, ומדוע נצרך הכתוב למעט אפשרות זאת?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם],\u0006 שאין קדושת המזבח חלה על בהמה שקדושה כבר לבדק הבית, הרי זה מפני ש\u0003כל\u0004 סתם \u0003בהמה לאו לעולה קיימא\u0004 \u0005[אינה עומדת\u0006 מתחילתה להיות מוקדשת \u0005לעולה],\u0006 כלומר, להקרבה על המזבח, ולכן לאחר שהקדישוה לבדק הבית, אי אפשר להוסיף עליה קדושה למזבח. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 ש\u0003כל\u0004 סתם \u0003בהמה ל\u0004מצות \u0003מעשר קיימא\u0004 \u0005[עומדת],\u0006 שהרי אדם מעשר את כל בהמותיו, הרי \u0003אף על גב דאקדשה\u0004 \u0005[אף על פי שהקדיש אותה]\u0006 מתחילה לשלמים, יש לומר כי \u0003לא פקע איסורא דמעשר מינה\u0004 \u0005[איסור,\u0006 חובת, \u0005המעשר ממנה].\u0006","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה משמעות הדבר להלכה — שאם הקדישה כמעשר הריהי \u0003ב\u0004איסור \u0003\"לא יגאל\"\u0004 (ויקרא כז, לג) \u0003ו\"לא ימכר\",\u0004 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא, שקדושת מעשר אינה חלה על שלמים, וניתן לפדותם כשנופל בהם מום.","שנינו במשנה: \u0003ונוהג\u0004 מעשר בהמה \u0003בבקר ובצאן ואין מתעשרין מזה על זה. בכבשים ובעזים\u0004 ומתעשרין מזה על זה. שהיה בדין: ומה אם החדש והישן שאינן כלאים זה בזה אינם מתעשרים וכו'. ומביאים ברייתא בענין זה: \u0003ויהיו חדש וישן מתעשרין מזה על זה מקל וחומר: ומה כבשים ועזים שהם כלאים זה בזה\u0004 — \u0003מתעשרין מזה על זה, חדש וישן\u0004 בהמות שנולדו בשנה זו ובשנה שלפניה, \u0003שאינן כלאים זה בזה\u0004 — \u0003אינו דין שיתעשרו מזה על זה?\u0004","\u0003תלמוד לומר: \"עשר תעשר\u0004 את כל תבואת זרעך היצא השדה שנה שנה\" (דברים יד, כב), והלשון \"עשר תעשר\" מרמזת כי \u0003בשתי מעשרות הכתוב מדבר, אחד מעשר בהמה ואחד מעשר דגן, ו\u0004בכך \u0003מקיש\u0004 (משווה) הכתוב \u0003מעשר בהמה למעשר דגן: מה מעשר דגן מחדש על הישן לא\u0004 מעשרים, שהרי נאמר שם \"שנה שנה\" — \u0003אף מעשר בהמה מחדש על הישן לא\u0004 מעשרים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 לענין \u0003כבשים ועזים נמי לימא\u0004 \u0005[גם כן נאמר]\u0006 באותו אופן: \u0003מקיש מעשר בהמה למעשר דגן, מה מעשר דגן ממין על שאינו מינו לא\u0004 מעשרים — \u0003אף מעשר בהמה ממין על שאינו מינו לא\u0004 מעשרים, ומדוע כבשים ועזים מתעשרים מזה על זה? ומשיבים: \u0003רבי רחמנא\u0004 \u0005[ריבתה התורה]\u0006 במצות מעשר בהמה ואמרה \u0003\"צאן\",\u0004 כדי ללמדנו שכל מה שהוא בכלל צאן מתעשר מזה על זה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שריבתה התורה, \u0003חדש וישן נמי\u0004 \u0005[גם כן]\u0006 יתעשרו מזה על זה במעשר בהמה! ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"עשר תעשר\",\u0004 ובכך הקישה התורה מעשר בהמה למעשר דגן, ללמד שאינו מתעשר מן החדש על הישן. ושואלים: \u0003ומה ראית\u0004 להקיש לענין חדש וישן, ולא להקיש לענין כבשים ועיזים? \u0003אמר רבא: אמר\u0004 שם \u0003קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"שנה שנה\"\u0004 — ללמדנו שלענין \u0003שנה הקשתיו,\u0004 שלא יתרום מהחדש על הישן, \u0003ולא לדבר אחר.\u0004","ובענין הפרשה ממין על שאינו מינו, \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת תרומות: \u0003אין תורמין ממין על שאינו מינו, ואם תרם\u0004 — \u0003אין תרומתו תרומה.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' אמי אמר ר' ינאי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר ר' אמי אמר ר' שמעון בן לקיש:\u0004 נאמר בענין תרומה \u0003\"כל חלב יצהר\u0004 (שמן) \u0003וכל חלב תירוש\u0004 (יין) \u0003ודגן\u0004 ראשיתם אשר יתנו לה' לך נתתים\" (במדבר יח, יב), ובמה שחזרה התורה על לשון \"חלב\" — \u0003אמרה תורה: תן חלב\u0004 (תרומה) \u0003לזה\u0004 ליצהר בנפרד, \u0003וחלב לזה\u0004 ליין בנפרד, ולא שיתן תרומה מזה על זה."],["ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 איפוא\u0005]\u0006 מקור בתורה לגבי \u0003תירוש ויצהר,\u0004 שאינם מתעשרים מזה על זה, שהרי לכל אחד מהם נאמר \"חלב\" בפני עצמו, אבל \u0003תירוש ודגן,\u0004 או \u0003דגן ודגן,\u0004 כגון חיטה ושעורה, \u0003מנין\u0004 שלא יביא תרומה ממין על מין אחר? ומשיבים, דבר זה נלמד מ\u0003קל וחומר: ומה תירוש ויצהר שאינן כלאים זה בזה,\u0004 שמותר לזרוע יחד חרצנים של גפן וזית — \u0003אין מתעשרין מזה על זה, תירוש ודגן, דגן ודגן, שהם כלאים זה בזה,\u0004 שאסור לזורעם יחד — \u0003אינו דין שלא יתעשרו מזה על זה?\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' יאשיה\u0004 ש\u0003אמר:\u0004 אין איסור זריעה של כלאים מהתורה \u0003עד שיזרע חטה ושעורה\u0004 (שני מיני דגן) \u0003ו\u0004גם \u0003חרצן\u0004 של ענב \u0003במפולת יד,\u0004 בזריעה אחת, \u0003היכי מייתי לה\u0004 \u0005[איך\u0006 הוא \u0005מביא אותה],\u0006 איך הוא לומד שתירוש ודגן או דגן ודגן אינם מתעשרים מזה על זה?","ומשיבים: \u0003מייתי לה הכי\u0004 \u0005[\u0006הוא \u0005מביא,\u0006 לומד, \u0005אותה כך]:\u0006 \u0003ומה תירוש ויצהר, שאינן כלאים זה בזה אפילו על ידי דבר אחר,\u0004 שאפילו היה זורע מין דגן נוסף עימם לא היו נאסרים — בכל זאת \u0003אין מתעשרין מזה על זה, תירוש ודגן\u0004 (כגון חיטה וחרצן), וכן \u0003דגן ודגן\u0004 (חיטה ושעורה), \u0003שהן כלאים זה בזה על ידי דבר אחר,\u0004 כשמוסיף שעורה לחיטה ולחרצן, או כשמוסיף חרצן לחיטה ולשעורה — \u0003אינו דין שלא יתעשרו מזה על זה?\u0004 ושואלים: למדנו, איפוא, שאין תורמים ומעשרים ממין על שאינו מינו, לגבי דגן תירוש ויצהר, שנזכרו בכתוב.","\u0003ושני מינין בעלמא\u0004 \u0005[בכלל],\u0006 \u0003מנלן\u0004 \u0005[מנין לנו],\u0006 שאין תורמים ומעשרים מזה על זה? ומשיבים: \u0003הני\u0004 \u0005[אלו],\u0006 המינים האחרים \u0003דרבנן נינהו\u0004 \u0005[מדברי סופרים הם],\u0006 שחובת הפרשת תרומות ומעשרות בשאר המינים אינה מן התורה, \u0003וכל דתקינו רבנן כעין דאורייתא תקינו\u0004 \u0005[וכל שתיקנו חכמים כעין\u0006 דין \u0005תורה תיקנו]:\u0006 \u0003מה\u0004 בתרומות ומעשרות \u0003דאורייתא\u0004 \u0005[של תורה]\u0006 \u0003שני מינין אינן מתעשרין מזה על זה\u0004 — אף בתרומות ומעשרות \u0003דרבנן נמי\u0004 \u0005[של\u0006 דברי \u0005חכמים גם כן]\u0006 אין מעשרים ממין על מין אחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי: אלא מעתה,\u0004 שאין תורמים ממין על שאינו מינו, ממה שחילקה התורה \"כל חלב יצהר, וכל חלב תירוש ודגן\", אם כן, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מעשר בהמה, דלא כתיב\u0004 \u0005[שלא נאמר]\u0006 \u0003\"וכל מעשר בקר ומעשר צאן\",\u0004 \"מעשר\" לגבי בקר לחוד, ו\"מעשר\" לגבי צאן לחוד, אלא נאמר: \"וכל מעשר בקר וצאן\" (ויקרא כז, לב),"],["\u0003יתעשרו מזה על זה! אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"וכל מעשר בקר וצאן כל אשר יעבר תחת השבט \u0003העשירי\u0004 יהיה קדש לה' \" (ויקרא כז, לב), ומלה זו שהיא מיותרת באה להדגיש: \u0003תן עשירי לזה ותן עשירי לזה,\u0004 לכל מין בפני עצמו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003כבשים ועזים נמי\u0004 \u0005[גם כן]\u0006 לא יתעשרו זה על זה! ומשיבים: מה שנאמר שם \u0003\"וצאן\"\u0004 (ויקרא כז, לב), ולא \"כבשים ועזים\", \u0003משמע\u0004 ממנו ש\u0003כל\u0004 סוגי \u0003צאן\u0004 הם מין \u0003אחד\u0004 למעשר.","ושואלים: אם כך, \u0003הכא נמי לימא\u0004 \u0005[כאן גם כן,\u0006 לגבי תרומות ומעשרות, \u0005נאמר]\u0006 כי \"דגן\" \u0003משמע\u0004 ש\u0003כל\u0004 סוגי \u0003דגן אחד\u0004 הם, ומפרישים מחיטה על שעורה! \u0003אמר אביי:\u0004 נאמר \"כל חלב יצהר וכל חלב תירוש ודגן \u0003ראשיתם\"\u0004 (במדבר יח, יב), בלשון רבים, ומכך למדים שנותנים \"ראשית\" (תרומה) לכל מין ומין. ומעירים: \u0003וכן אמר ר' אילעא:\u0004 נאמר \u0003\"ראשיתם\"\u0004 בלשון רבים ללמד על נתינת \"ראשית\" לכל מין ומין.","\u0003רבא אמר:\u0004 \u0003בלא\u0004 הלימוד מ\u0003\"ראשיתם\" נמי\u0004 \u0005[גם כן]\u0006 אין בכך קושי, כי לומר ש\u0003משמע\u0004 מן המלה \"דגן\" ש\u0003כל\u0004 סוגי \u0003דגן אחד\u0004 הם, לענין תרומות ומעשרות — \u0003לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר]\u0006 כמו \"וצאן\" לענין מעשר בהמה, שכן \u0003בשלמא התם אמרינן\u0004 \u0005[נניח שם אומרים אנו]:\u0006 \u0003\"וצאן\" משמע\u0004 ממנו ש\u0003כל צאן אחד\u0004 למעשר, מפני \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 ש\u0003כבשים ועזים נמי\u0004 \u0005[גם כן]\u0006 אין מעשרים מזה על זה — \u0003לכתוב\u0004 \u0005[שתכתוב]\u0006 התורה בלשון כללית: \u0003\"וכל מעשר בהמה\",\u0004 ולא תחלק בין בקר וצאן, והיינו אומרים שכל מיני הבהמה, וגם כבשים ועזים, אין מתעשרים מזה על זה, כפי שיבואר להלן.","ותחילה מעירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005נאמר]\u0006 \u0003\"כל מעשר בהמה\" הוי אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003אפילו חיה\u0004 חייבת במעשר, מפני שחיה בכלל בהמה, ולכן הוצרך לומר \"בקר וצאן\" — דבר זה יש לדחות, שכן דין זה בגזירה שווה \u0003\"תחת\" \"תחת\" מ\u0004שאר \u0003קדשים גמר\u0004 \u0005[למד]\u0006 (ויקרא כב, כז. ויקרא כז, לב כז, לב), שאין חיה בכלל הציווי.","וחוזרים לדברים שנאמרו למעלה, שאם נניח שכבשים ועזים מתעשרים מזה על זה, אפשר היה לכתוב \"וכל מעשר בהמה\", \u0003ואתי\u0004 \u0005[ובא,\u0006 נלמד\u0005]\u0006 שאין מעשרים ממיני הבהמה זה על זה, \u0003בקל וחומר מחדש וישן,\u0004 שאינם כלאים, ואף על פי כן אין מעשרים מזה על זה. ואם כן, מה שחילקה התורה \u0003\"בקר וצאן\" למה לי?\u0004 אלא בא הדבר לומר: \u0003בקר וצאן הוא\u0004 ש\u0003אין מתעשרין מזה על זה, אבל כבשים ועזים,\u0004 שהם בכלל \"צאן\" — \u0003מתעשרין\u0004 מזה על זה.","\u0003אבל הכא\u0004 \u0005[כאן],\u0006 לענין \"דגן\" האמור בתרומות ומעשרות — \u0003מי סגיא\u0004 \u0005[האם אפשר]\u0006 \u0003דלא כתיב\u0004 \u0005[שלא ייכתב]\u0006 בפסוק זה \u0003דגן\u0004 כלל? הרי צריך לכתוב אותו לגופו, לחייבו בתרומות ומעשרות, יחד עם תירוש ויצהר, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שאר מינין,\u0004 שאינם חייבים בתרומה ומעשר מן התורה. ולכן אין מקום ללמוד ממנו שכל מיני הדגן מין אחד הם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן:\u0004 מנין לרבא שהייתור \"בקר וצאן\" מלמדנו שאינם מתעשרים מזה על זה? \u0003אימא\u0004 \u0005[אמור]\u0006 שיש ללמוד מכאן \u0003לערבו\u0004 \u0005[שיערבו]\u0006 \u0003לבקר בצאן,\u0004 ויתעשרו מזה על זה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: לרבא אית ליה נמי\u0004 \u0005[יש לו גם כן]\u0006 דרשה זו של \u0003\"העשירי\",\u0004 המלמדת שצריך לתת מעשר לבקר לעצמו ולצאן לעצמו. עד כאן מהלך הסוגיה לפי דרך אחת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך: לאחר שהסביר אביי כי בקר וצאן אינם מתעשרים מזה על זה בגלל יתור המלה \"העשירי\", המלמד: תן עשירי לזה ועשירי לזה, \u0003אמר רבא:\u0004 אף \u0003בלא\u0004 דרשת \u0003\"עשירי\" נמי לא מצית אמרת\u0004 \u0005[גם כן אין אתה יכול לומר]\u0006 שבקר וצאן מתעשרין מזה על זה, דאיתקש \u0005[ש\u0006הרי \u0005הוקש]\u0006 בכתוב \u0003מעשר בהמה למעשר דגן,\u0004 שנאמר \"עשר תעשר\" (דברים יד, כב), וכפל הלשון מורה על שני מעשרות, מעשר דגן ומעשר בהמה, ומן ההיקש למדים: \u0003מה מעשר דגן\u0004 — \u0003ממין על שאינו מינו לא\u0004 מעשרים, \u0003אף מעשר בהמה\u0004 — \u0003ממין על שאינו מינו לא\u0004 מעשרים.","ומקשים, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוא\u0004 ש\u0003אמר\u0004 כי אין למדים מכאן דין זה, שכן ממה שנאמר כאן \u0003\"שנה\u0004 שנה\" יש ללמוד כי \u0003לשנה\u0004 בלבד \u0003הקשתיו,\u0004 את מעשר הבהמה למעשר דגן, ללמד שלא יעשר מהחדש על הישן, \u0003ולא לדבר אחר!\u0004 ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא מההיא. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003חדא מיניה\u0004 \u0005[אחת מהם,\u0006 מאותם שני ההסברים\u0005]\u0006 \u0003רב פפא אמרה\u0004 ולא רבא. שכיון שרב פפא היה תלמידו המובהק של רבא, וראש ישיבה אחריו, פעמים שאמרו את דברי התלמיד בתור דברי הרב.","עדר החייב ב\u0003מעשר בהמה מצטרף\u0004 לחיוב אם היו הבהמות מרוחקות \u0003כמלא רגל בהמה רועה,\u0004 כמרחק שבהמה רועה ועדיין משתמרת על ידי רועה אחד. \u0003וכמה היא רגל בהמה רועה? ששה עשר מיל. היו בין אלו לאלו שלשים ושנים מיל\u0004 — \u0003אין מצטרפין. היו לו\u0004 צאן גם \u0003באמצע\u0004 בתוך מרחק זה של שלושים ושנים מיל — \u0003מביא\u0004 את כולן לדיר, \u0003ומעשרן באמצע. ר' מאיר אומר: הירדן מפסיק למעשר בהמה,\u0004 והבהמות שבשני עבריו אינן מצטרפות, אף על פי שהן קרובות.","שנינו במשנה שמעשר בהמה מצטרף כמלא רגל בהמה רועה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שבהמות שבמרחק זה מצטרפות לחיוב במעשר?","\u0003אמר רבה בר שילא: דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"עוד תעברנה הצאן על ידי מונה\"\u0004 (ירמיהו לג, יב—יג), כלומר, על ידי רועה, שאם כולן יכולות להימנות על הרועה, כשהוא רואה את כולן — הרי זה בכלל עדר צאן העובר תחת השבט להתעשר. \u0003וקים להו לרבנן\u0004 \u0005[ומוחזק להם לחכמים]\u0006 \u0003דשיתסר מיל קא שלטא ביה עינא דרועה\u0004 \u0005[ששישה עשר מיל שולטת בו עין הרועה],\u0006 ולא ביותר מזה.","שנינו במשנתנו: \u0003היו בין אלו לאלו שלשים ושנים מיל אין מצטרפין וכו'.\u0004 ושואלים: \u0003שלשים ושנים הוא\u0004 ש\u0003אין מצטרפין\u0004 לעדר החייב במעשר, \u0003הא בציר מהכי\u0004 \u0005[אבל פחות מזה]\u0006 \u0003מצטרפין? והא קתני\u0004 \u0005[והרי שנה]\u0006 במשנתנו מתחילה \u0003ששה עשר מיל, טפי\u0004 \u0005[יותר]\u0006 מכך \u0003לא\u0004 מצטרפים! ומשיבים, מה שהוזכר ששלושים ושנים אינם מצטרפים לא נאמר אלא \u0003משום דקא בעי למיתנא סיפא\u0004 \u0005[שהוא צריך לשנות בסוף,\u0006 בהמשך\u0005]:\u0006 \u0003היו לו\u0004 בהמות \u0003באמצע\u0004 שלושים ושנים מיל — \u0003מביא ומעשרן באמצע.\u0004 ואין לדייק ממנו שבפחות מכאן הרי אלו מצטרפים.","ושואלים: \u0003וכמה\u0004 יהיו לו בצדדים ובאמצע כדי שיצטרפו? \u0003אמר רב:\u0004 כגון שהיו \u0003חמש מכאן וחמש מכאן וחמש מאמצע, דהני חמש חזיא להכא וחזיא להכא\u0004 \u0005[ש\u0006אותן \u0005החמש שבאמצע ראויות\u0006 להצטרף \u0005לכאן וראויות\u0006 להצטרף \u0005לכאן]\u0006 למנין עשר בהמות החייבות במעשר, ולכן כולן נחשבות לעדר אחד.","\u0003ושמואל אמר: אפילו חמש מכאן וחמש מכאן ואחד באמצע\u0004 די בהן כדי לצרפן, שכן \u0003חזינן לרועה כמאן דקאי הכא\u0004 \u0005[רואים אנו את הרועה כמי שעומד כאן]\u0006 אצל זו שבאמצע, \u0003וקרינן ביה\u0004 \u0005[וקוראים אנו בו]\u0006 \u0003\"מונה\",\u0004 שיכול למנות את אלו וגם את אלו בעיניו, והן נחשבות לעדר אחד."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב ממה ששנינו בברייתא: \u0003היה לו חמש\u0004 צאן \u0003בכפר חנניה וחמש בכפר עותני,\u0004 כיון שהם רחוקים זה מזה — \u0003אין מצטרפות עד שיהא לו\u0004 צאן \u0003אחת בציפורי\u0004 שהיא באמצע. הרי זה \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב\u0004 שהצריך שיהיו חמש באמצע!","\u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 \u0003שמואל אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003רב: כגון שהיו\u0004 לו, לא חמש, אלא \u0003תשע מכאן ותשע מכאן ואחת באמצע, דההיא חזיא להכא וחזיא להכא\u0004 \u0005[שאותה\u0006 אחת \u0005ראויה\u0006 להצטרף \u0005לכאן וראויה\u0006 להצטרף \u0005לכאן],\u0006 שבכל מקום היא משלימה לעשרה.","\u0003אמר רב פפא: ול\u0004דעת \u0003שמואל,\u0004 שאמר שדי שתהיה אחת באמצע — \u0003אפילו\u0004 ה\u0003רועה\u0004 שנמצא באמצע, בלי צאן, \u0003מצרפן, ואפילו כליו של רועה\u0004 שנמצאים באמצע \u0003מצרפן,\u0004 מפני שהרועה צריך להגיע לשם כדי לקחתם, וכאילו הוא עצמו מצוי שם.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: כלבא\u0004 \u0005[כלבו]\u0006 של ה\u0003רועה מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 האם \u0003כיון דקרי ליה ואתי לא מצטרפי\u0004 \u0005[ש\u0006הוא \u0005קורא לו\u0006 לכלב, \u0005ו\u0006הוא \u0005בא אליו, אינם מצטרפים],\u0006 \u0003או דלמא זימנין דלא אתי\u0004 \u0005[או שמא פעמים שאין\u0006 הכלב \u0005בא]\u0006 כשהוא קורא לו, \u0003ומצטרך איהו למיזל ואתייה\u0004 \u0005[וצריך הוא ללכת ולהביא אותו],\u0006 ונחשב הדבר כאילו הוא מצוי שם? שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה, ר' מאיר אומר: הירדן מפסיק למעשר \u0003בהמה. אמר ר' אמי: לא שנו אלא שאין שם גשר\u0004 על הירדן בין העדרים, \u0003אבל\u0004 אם \u0003יש שם גשר\u0004 — ה\u0003גשר מצרפן.\u0004","ומדייקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהטעם שהירדן מפסיק למעשר בהמה — \u0003משום דלא מיקרבן\u0004 \u0005[ש\u0006הצאן \u0005אינן קרובות]\u0006 \u0003הוא,\u0004 שאינן יכולות להגיע מכאן לשם. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003היו לו\u0004 צאן \u0003בשני עברי הירדן אילך ואילך, או בשני אבטילאות\u0004 (מחוזות) \u0003כגון של נמר ונמורי\u0004 — \u0003אין מצטרפין\u0004 למעשר בהמה, למרות שאין נהר מפריד ביניהם, \u0003ואין צריך לומר\u0004 אם היו לו ב\u0003חוצה לארץ ו\u0004ב\u0003ארץ.\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003חוצה לארץ וארץ כמקום שיש גשר דמי\u0004 \u0005[נחשב],\u0006 שהרי הגבול עובר גם במקום שאין נהר או מכשול אחר, \u0003וקתני\u0004 \u0005[ו\u0006הוא \u0005שונה]:\u0006 \u0003לא מצטרפין!\u0004","\u0003אלא אמר ר' חייא בר אבא אמר ר' יוחנן: היינו טעמיה\u0004 \u0005[זהו טעמו]\u0006 של \u0003ר' מאיר,\u0004 שאמר שהירדן מפסיק למעשר בהמה — \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 בנחלת שבט בנימין: \u0003\"והירדן יגבל אתו לפאת קדמה\"\u0004 (יהושע יח, כ), \u0003הכתוב עשאו\u0004 את הירדן \u0003גבול בפני עצמו.\u0004","ומקשים: \u0003אלא מעתה,\u0004 כל מקום שנאמר בנחלות השבטים \u0003\"ותאר הגבול\" \"ועלה הגבול\"\u0004 (ראה יהושע יב, יד), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003הכתוב עשאו גבול בפני עצמו,\u0004 וגבול השבטים מפסיק למעשר בהמה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 בענין גבולות השבטים, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"זאת תהיה לכם הארץ לגבלתיה סביב\"\u0004 (במדבר לד, יב), לומר — \u0003כולה ארץ ישראל\u0004 על כל הגבולות שיש בתוכה, \u0003גבול אחד היא.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ירדן נמי\u0004 \u0005[גם כן]\u0006 ייחשב בכלל זה! ומשיבים: הכוונה שם לגבולות של \u0003ארץ\u0004 (קרקע), \u0003ולא ירדן,\u0004 שהוא נהר.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' חייא בר אבא,\u0004 שטעמו של ר' מאיר תלוי בגזירת הכתוב — \u0003היינו דקתני\u0004 \u0005[זהו שהוא שונה]\u0006 שדוקא \u0003ירדן\u0004 מפסיק למעשר בהמה. \u0003אלא ל\u0004שיטת \u0003ר' אמי,\u0004 שהוא מפסיק משום שאין הבהמות יכולות לעבור — \u0003ליתנינהו לכולהו\u0004 \u0005[שישנה\u0006 אם כן \u0005את כל]\u0006 ה\u0003נהרות,\u0004 שהם מפסיקים למעשר בהמה! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 כי השאלה האם ירדן עצמו בכלל ארץ ישראל, שנויה \u0005כ\u0006מחלוקת \u0005תנאים],\u0006 שכך שנינו בברייתא: נאמר \u0003\"כי אתם עברים את הירדן ארצה כנען\"\u0004 (במדבר לה, ו), ומכאן יש לדייק: \u0003\"ארצה\"\u0004 — \u0003ארץ כנען, ולא הירדן\u0004 נחשב ל\u0003ארץ כנען,\u0004 אלו \u0003דברי ר' יהודה בן בתירה.\u0004","\u0003ר' שמעון בן יוחי אומר: הרי הוא אומר\u0004 \"שני המטות וחצי המטה לקחו נחלתם \u0003מעבר לירדן ירחו קדמה מזרחה\"\u0004 (במדבר לד, טו), \u0003מה ירחו\u0004 היא \u0003ארץ כנען, אף\u0004 ה\u0003ירדן\u0004 הנזכר עמה שייך ל\u0003ארץ כנען.\u0004","ועוד בעניינו של הירדן, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: אין\u0004 קוראים \u0003\"ירדן\" אלא מבית ירחו ולמטה,\u0004 כלומר, דרומה. ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004ענין של \u0003נודר,\u0004 כגון שנודר שלא ישתה מן הירדן, הלא בענין נדרים כלל בידינו ש\u0003הלך אחר לשון בני אדם, וכל היכא דקרו ליה\u0004 \u0005[וכל מקום שקוראים לו]\u0006 אנשים \u0003\"ירדן\" איתסר ליה\u0004 \u0005[נאסר לו]!\u0006 \u0003אלא\u0004 דברי ר' יוחנן נוגעים \u0003ל\u0004ענין \u0003מעשר בהמה,\u0004 שהירדן מפסיק בין שני עבריו רק מבית ירחו ולמטה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ירדן יוצא ממערת פמייס, ומהלך\u0004 (עובר) \u0003בימה של סיבכי\u0004 (ים החולה), \u0003ובימה של טבריא, ובימה של סדום\u0004 (ים המלח), \u0003והולך ונופל\u0004 משם מתחת לאדמה עד \u0003לים הגדול, ואין\u0004 נקרא \u0003\"ירדן\" אלא מבית יריחו ולמטה.\u0004","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: למה נקרא שמו \"ירדן\"?\u0004 מפני \u0003שיורד מ\u0004העיר \u0003דן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: אתון מהתם מתניתו לה\u0004 \u0005[אתם משם אתם שונים אותה],\u0006 \u0003אנן מהכא מתנינן לה\u0004 \u0005[אנו מכאן אנו שונים אותה],\u0006 שנאמר על בני שבט דן: \u0003\"ויקראו לו ללשם דן בשם דן אביהם\"\u0004 (יהושע יט, מז), \u0003ו\u0004בזיהויו של מקום זה \u0003אמר ר' יצחק: לשם זו פמייס,\u0004 הרי שפמייס היא דן. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003יוצא ירדן ממערת פמייס.\u0004","ועוד בענין זה מביאים מה ש\u0003אמר רב כהנא: זכרותיה דירדנא\u0004 \u0005[עיקרו,\u0006 מקורו \u0005של הירדן]\u0006 הוא \u0003ממערת פמייס,\u0004 ולכן \u0003היכא דאמר\u0004 \u0005[במקום ש\u0006הוא \u0005אומר]:\u0006 \u0003לא שתינא\u0004 \u0005[אין אני שותה]\u0006 \u0003מים ממערת פמייס\u0004 — \u0003איתסר ליה בכוליה ירדנא\u0004 \u0005[נאסר לו\u0006 לשתות \u0005בכל הירדן].\u0006","\u0003זכרותא דדמא כבדא\u0004 \u0005[עיקרו,\u0006 מקורו \u0005של הדם הוא הכבד],\u0006 ומשמעות הדברים להלכה היא \u0003כ\u0004דברי \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: כבד\u0004 של מת \u0003שנימוח\u0004 — \u0003מטמא ב\u0004שיעור \u0003רביעית,\u0004 כדין דם המת, משום שהוא כולו מלא דם, ולא בכזית, כדין בשר המת.","\u0003זכרותא דמיא\u0004 \u0005[המקור של\u0006 כל \u0005המים]\u0006 הוא נהר \u0003פרת.\u0004 ש\u0003אמר רב יהודה אמר רב: הנודר ממימי פרת\u0004 — \u0003אסור בכל מימות שבעולם.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דאמר\u0004 \u0005[אם תאמר שאומר]\u0006 \u0003\"לא שתינא ממימי דפרת\"\u0004 \u0005[אין אני שותה מן המים של פרת]\u0006 — אם כן כוונתו: \u0003מי פרת\u0004 עצמם \u0003הוא דלא שתינא\u0004 \u0005[שאין אני שותה],\u0006 \u0003הא מנהרא אחרינא שתינא\u0004 \u0005[אבל מנהר אחר אני שותה].\u0006","\u0003אלא\u0004 הכוונה היא \u0003דאמר\u0004 \u0005[שאומר]\u0006 בלשון זו: \u0003\"לא שתינא\u0004 \u0005[אין אני שותה]\u0006 \u0003ממים דאתו\u0004 \u0005[שבאים]\u0006 \u0003מפרת\",\u0004 ודוקא בזה נאסרים עליו כל הנהרות. שכן \u0003אמר רב יהודה אמר רב: כל הנהרות\u0004 הם \u0003למטה,\u0004 כלומר, באים \u0003משלש נהרות,\u0004 פישון גיחון וחדקל (בראשית יא—יד), \u0003ושלש נהרות למטה מפרת.\u0004 ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006"],["\u0003עינתא דמידליין\u0004 \u0005[מעיינות ש\u0006ב\u0005מרומי\u0006 ההרים\u0005],\u0006 ואיך אפשר לומר שהם באים מהפרת! \u0003אמר רב משרשיא: הנהו סולמי דפרת נינהו\u0004 \u0005[אלו סולמות של פרת הם],\u0006 שמי הפרת מחלחלים תחת הקרקע ועולים ונובעים באותם מעיינות. ומקשים עוד: וכיצד ייתכן שכל הנהרות נמשכים מן הפרת?","\u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \"ונהר יוצא מעדן להשקות את הגן ומשם יפרד והיה לארבעה ראשים... \u0003והנהר הרביעי הוא פרת\"\u0004 (בראשית ב, י—יד), ומשמע שהוא אחרון הנהרות, ולא הראשון!","\u0003אמר רב נחמן בר יצחק, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אחא בר יעקב:\u0004 מה שנאמר \u0003\"הוא פרת\"\u0004 פירושו שפרת הוא הנהר \u0003דמעיקרא\u0004 \u0005[ש\u0006הוזכר \u0005מתחילה],\u0006 הנהר היוצא מעדן, שממנו יוצאים כולם, ולאחר מכן הוא ממשיך במהלכו.","וכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: \"יובל\" שמו\u0004 של נהר הפרת היוצא מעדן, \u0003שנאמר: \"והיה כעץ שתול על מים ועל יובל ישלח שרשיו\"\u0004 (ירמיהו יז, ח), ולדעתו כוונת הנאמר היא לעץ החיים, שהוא שתול בגן עדן, והוא שולח את שרשיו על נהר היובל היוצא משם. \u0003ולמה נקרא שמו \"פרת\"\u0004 — מפני \u0003שמימיו פרים ורבים\u0004 מעצמם, בלא מטר.","ואומרים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003ל\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: נהרא מכיפיה מיבריך\u0004 \u0005[הנהר מגדותיו הוא מתברך\u0006 במים\u0005].\u0006 \u0003ופליגא\u0004 \u0005[וחלוק]\u0006 שמואל על מה שאמר \u0003רב,\u0004 ש\u0003אמר רב אמי אמר רב: מיטרא במערבא סהדא רבה\u0004 \u0005[\u0006כשיש \u0005מטר בארץ ישראל העד הגדול\u0006 על ירידתו\u0005]\u0006 הוא \u0003פרת,\u0004 שמימיו מתרבים מפני המטר שמגיע אליו משם.","מסופר, \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל עביד להו לבנאתיה\u0004 \u0005[היה עושה להן לבנותיו]\u0006 \u0003מקוה ביומי\u0004 \u0005[בימי]\u0006 \u0003ניסן\u0004 כדי שיטבלו בו, ולא יטבלו בנהר, והיה עושה להן \u0003מפצי ביומי\u0004 \u0005[מחצלות\u0006 לצניעות \u0005בימי]\u0006 \u0003תשרי,\u0004 שאז התיר להם לטבול בנהר. ומסבירים: מה שהיה עושה להן \u0003מקוה ביומי\u0004 \u0005[בימי]\u0006 \u0003ניסן,\u0004 הרי זה מפני שבאותו זמן מתרבים מאד מי הנהר, ואביו של שמואל \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003רב,\u0004 ש\u0003אמר רב אמי אמר רב: מיטרא במערבא סהדא רבה\u0004 \u0005[מטר בארץ ישראל העד הגדול]\u0006 הוא נהר \u0003פרת,\u0004 והיה חושש \u0003שמא ירבו\u0004 המים ה\u0003נוטפין\u0004 (מי הגשמים) \u0003על הזוחלין\u0004 (מי הנהר עצמו), \u0003והוו להו\u0004 \u0005[ויהיו להם]\u0006 \u0003מי גשמים רובא\u0004 \u0005[רוב],\u0006 ולכן יקבל כל הנהר דין מי גשמים, שאין לטבול בהם כשהם זורמים, עד שייקוו במקום אחד ל\"מקוה\".","\u0003ו\u0004מה שהיה עושה להן \u0003מפצי ביומי\u0004 \u0005[מחצלות\u0006 לצניעות \u0005בימי]\u0006 \u0003תשרי,\u0004 והתיר לטבול בנהר, הרי זה מפני שבאותה תקופה רוב מימיו היו מי מעיינות הכשרים לטבול בהם, גם כאשר הם זורמים.","ושבים לדברי שמואל, שאמר שהנהר מתברך מעצמו, ומעירים: \u0003ופליגא דידיה אדידיה\u0004 \u0005[וחלוקים\u0006 דבריו \u0005שלו על\u0006 דבריו \u0005שלו],\u0006 ש\u0003אמר שמואל\u0004 עצמו: \u0003אין המים נטהרים\u0004 (מטהרים) \u0003בזוחלין\u0004 (שלא במקוה) \u0003אלא\u0004 נהר \u0003פרת ביומי\u0004 \u0005[בימי]\u0006 \u0003תשרי,\u0004 שאז רוב המים שבו הם מי הנהר עצמו, אבל בשאר ימות השנה יש לחשוש לריבוי מי גשמים.","\u0003הלוקח\u0004 (הקונה) צאן ובקר, \u0003או שניתן לו במתנה\u0004 — הרי זה \u0003פטור ממעשר בהמה.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב כהנא: דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 \u0003\"בכור בניך תתן לי, כן תעשה לשרך לצאנך\"\u0004 (שמות כב, כח—כט),"],["\u0003מה\u0004 פדיית בכור \u0003בניך\u0004 — \u0003אין\u0004 נוהגת \u0003בלקוח ובמתנה,\u0004 שהרי היא שייכת רק בבנו שנולד ממנו, \u0003אף צאנך ובקרך\u0004 האמור שם — \u0003אינו\u0004 נוהג \u0003בלקוח ובמתנה.\u0004","ותמהים: \u0003והאי\u0004 \u0005[ו\u0006הלא כתוב \u0005זה]\u0006 \"כן תעשה לשורך לצאנך\" (שמות כב, כט) \u0003ב\u0004מצות פדית \u0003בכור\u0004 בהמה \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולא במצות מעשר בהמה! ומשיבים: \u0003אמר\u0004 שם \u0003קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כן תעשה\",\u0004 ו\u0003אם אינו ענין לבכור, דלא איתיה\u0004 \u0005[שאינו שייך]\u0006 \u0003בעשייה,\u0004 שאין האדם צריך להקדישו, שהרי \u0003ברחם\u0004 הוא \u0003קדוש\u0004 מעצמו — \u0003תנהו ענין למעשר בהמה,\u0004 שהוא מתקדש כשקורא לו \"עשירי קודש\".","ומקשים: גם אם אינו ענין לבכור — מנין שמדובר במעשר? \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003תנהו ענין לחטאת ולאשם,\u0004 ללמד שיהיו דוקא משלו ולא קנויים! ומשיבים: שורך וצאנך האמור כאן הרי הם \u0003דומיא\u0004 \u0005[בדומה]\u0006 לדין בכור \u0003בנך, מה בנך\u0004 — \u0003שאינו בא על חטא, אף צאנך ושורך\u0004 — \u0003שאינו בא על חטא,\u0004 ואלו באים על חטא, מה שאין כן מעשר בהמה.","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003תנהו ענין לעולה ולשלמים,\u0004 שצריך להקדישם, ואינם באים על חטא! ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בנך, מה\u0004 פדיון \u0003בנך\u0004 — \u0003שאינו בא בנדר ונדבה,\u0004 אלא חובה היא, \u0003אף צאנך ושורך\u0004 — שאינם באים בנדר ונדבה, ועולה ושלמים באים בנדר ונדבה.","ומקשים עוד, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003תנהו ענין לעולת ראייה,\u0004 שחייב להביא כל מי שעולה לרגל! ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בנך, מה בנך\u0004 הוא דבר \u0003שאין קבוע לו זמן,\u0004 אלא כשנולד הוא קדוש, \u0003אף שורך וצאנך\u0004 — \u0003שאין קבוע לו זמן,\u0004 ואילו עולת ראיה קבוע לה זמן, ברגל.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מבכור אתה למד שמעשר שאינו נוהג בלקוח, הרי שהיה צריך ללמוד גם: \u0003מה\u0004 פדיון \u0003בנך אינו בלקוח כלל,\u0004 שאין בו כל צד של קניה, \u0003אף\u0004 מעשר \u0003שורך וצאנך אינו בלקוח כלל! אלמה\u0004 \u0005[מפני מה]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן:\u0004 אם \u0003לקח\u0004 (קנה) \u0003עשרה עוברין\u0004 כשהם \u0003במעי אמן\u0004 ונולדו ברשותו — \u0003כולם נכנסין לדיר להתעשר,\u0004 משמע שיש לקוח שחייב במעשר!","\u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"תעשה\"\u0004 — \u0003בשעת עשייה מיעט הכתוב\u0004 את הלקוח, לומר שרק הלקוח בשעה שניתן להקריבו — אינו מתעשר. אבל עוברים הרי אי אפשר להקריבם.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר ר' אסי אמר ר' יוחנן: לקח עשרה עוברים במעי אמן\u0004 — \u0003כולן נכנסין לדיר להתעשר.\u0004 ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הלוקח או שניתן לו במתנה פטור מן מעשר בהמה,\u0004 ומדוע לא ייפטרו אלה?","\u0003אמר ר' אלעזר:\u0004 את \u0003ר' יוחנן חזאי בחילמא\u0004 \u0005[ראיתי בחלום]\u0006 וסימן הוא ש\u0003מילתא מעליא אמינא\u0004 \u0005[דבר טוב אומר]\u0006 היום: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"תעשה\"\u0004 — לומר: את הלקוח \u0003בשעת עשייה מיעט הכתוב\u0004 מדין מעשר, שקנאו בשעה שראוי להקריבו. ולא עוברים, שאינם ראויים להקרבה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' שמעון בן אליקים לר' אלעזר:\u0004 והלא שנינו בברייתא כי פסול \u0003הלקוח חל\u0004 גם \u0003על מחוסר זמן,\u0004 שלקחו קודם שעברו שבעת ימים מלידתו, למרות שאינו ראוי אז להקרבה. ואם כך יחול פסול לקוח גם על עובר קנוי!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זו אינה משנה,\u0004 כלומר, אין לסמוך עליה, שהיא משובשת, \u0003ואם תמצא לומר משנה\u0004 היא, ואינה טעות — שיטת \u0003ר' שמעון בן יהודה היא משום\u0004 (בשם) \u0003ר' שמעון,\u0004 ש\u0003אמר: מחוסר זמן נכנס לדיר להתעשר, והרי הוא\u0004 לענין זה \u0003כבכור, מה בכור קדוש לפני זמנו,\u0004 מיד כשנולד, קודם שעברו שבעת ימים, \u0003וקרב\u0004 רק \u0003לאחר זמנו,\u0004 מהיום השמיני והלאה — \u0003אף מחוסר זמן\u0004 מכניסו להתעשר, ואם יצא עשירי — \u0003קדוש לפני זמנו, וקרב לאחר זמנו\u0004 מיום השמיני והלאה.","ועוד בענין זה מסופר, \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב: איזהו אתנן\u0004 זונה, ששנו חכמים (להלן נז,א) \u0003שנכנס לדיר להתעשר? כל שנתנו לה\u0004 כאתנן \u0003וחזר ולקחו הימנה\u0004 (קנה אותו ממנה). והקשה המקשן: \u0003והא איפסיל ליה\u0004 \u0005[והרי נפסל לו]\u0006 ממצות מעשר \u0003ב\u0004דין \u0003לוקח,\u0004 כשקיבלה הזונה את האתנן!","ומעירים: \u0003אישתמיטתיה הא דאמר\u0004 \u0005[נשמטה,\u0006 נשכחה \u0005מן\u0006 המקשן \u0005זו שאמר]\u0006 \u0003ר' אסי אמר ר' יוחנן: לקח עשרה עוברין במעי אמן\u0004 — \u0003כולם נכנסין לדיר להתעשר.\u0004 ולפי זה יש לפרש את הברייתא — כשנתן לה עובר באתננה, וחזר ולקחו ממנה."],["ושואלים: ומדוע העמידה הברייתא בדין אתנן דוקא באופן שחזר ולקחו ממנה? \u0003ותיעשרה איהי\u0004 \u0005[ותעשר היא]\u0006 את הבהמה שקיבלה באתנן! ומשיבים: מדובר פה \u0003בזונה גויה\u0004 שאינה שייכת במצוות.","ושואלים: \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה]\u0006 \u0003בזונה ישראלית, ותיעשרה איהי\u0004 \u0005[ושתעשר היא]!\u0006 ומשיבים: \u0003קא משמע לן\u0004 \u0005[משמיע לנו\u0006 התנא\u0005]\u0006 שב\u0003זונה ישראלית לא הוי\u0004 \u0005[אינו נחשב]\u0006 כלל \u0003אתנן\u0004 שאסרה התורה להקריבו,","\u0003כ\u0004דברי \u0003אביי.\u0004 ש\u0003אמר אביי: זונה גויה\u0004 — \u0003אתננה אסור\u0004 בהקרבה, \u0003וכהן הבא עליה אינו לוקה משום\u0004 \"אלמנה וגרושה וחללה זונה את אלה לא יקח... ו\u0003לא יחלל זרעו\"\u0004 (ויקרא כא, יד—טו). \u0003זונה ישראלית\u0004 — \u0003אתננה מותר\u0004 בהקרבה, \u0003וכהן הבא עליה לוקה משום \"לא יחלל זרעו\".\u0004","ומסבירים: \u0003זונה גויה אתננה אסור\u0004 — מפני שהוא \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"תועבה\" \"תועבה\" מעריות,\u0004 שנאמר באתנן זונה: \"תועבת ה' \" (דברים כג, יט), ונאמר בפרשת איסורי עריות: \"כי כל אשר יעשה מכל התועבות האלה ונכרתו הנפשות העושות מקרב עמם\" (ויקרא יח, כט),","\u0003מה עריות\u0004 המוזכרות שם, הן נשים שחייבים עליהן כרת, \u0003דלא תפסי בהו קדושי\u0004 \u0005[שאין תופסים בהן קידושין]\u0006 — \u0003אף\u0004 לגבי \u0003זונה\u0004 שאתננה אסור, מדובר \u0003בהך דלא תפסי בה קדושי\u0004 \u0005[בזו שלא תופסים בה קידושין],\u0006 ובגויה אין תופסים קידושין (מה שאין כן בזונה ישראלית).","ומה שאמר אביי לגבי זונה גויה: \u0003וכהן הבא עליה אינו לוקה משום \"לא יחלל זרעו\"\u0004 — מפני ש\u0003\"לא יחלל זרעו\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 שצריך שהנולד ייחשב לזרעו ושיהיה מחולל, \u0003והאי\u0004 \u0005[וזה]\u0006 הנולד מגויה \u0003לאו זרעיה\u0004 \u0005[לא זרעו]\u0006 \u0003הוא\u0004 נחשב, אלא גוי, ונמצא שהלאו שבתורה לא נאמר על מקרה כזה.","\u0003האחין והשותפין,\u0004 כלומר, האחים שהם שותפים בירושת אביהם, בזמן \u0003ש\u0004הם \u0003חייבין בקלבון\u0004 (מטבע קטנה, שמוסיפים למחצית השקל), כלומר, בזמן שיש להם דין שותפים רגילים — הריהם \u0003פטורין\u0004 באותה שעה \u0003ממעשר בהמה.\u0004 ואם הם בשלב של שיתוף שבו \u0003חייבין במעשר בהמה\u0004 — הריהם \u0003פטורין מן הקלבון,\u0004 כדין בנים הסמוכים על שולחן אביהם.","ומפרטים: \u0003קנו,\u0004 כלומר, זכו בבהמות \u0003מתפיסת הבית,\u0004 מנכסי הירושה — \u0003חייבין\u0004 לעשר אותן הבהמות, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטורין\u0004 ממעשר בהמה. כיצד? אם \u0003חלקו\u0004 בינם את ירושת אביהם ו\u0003חזרו ונשתתפו\u0004 בהם — \u0003חייבין בקלבון, ופטורין ממעשר בהמה\u0004.","בענין ששנינו במשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"...וכל פטר שגר בהמה אשר \u0003יהיה לך\"\u0004 (שמות יג, יב) — דוקא לך, היחיד, \u0003ולא של שותפות. יכול אפילו\u0004 אחים ש\u0003קנו\u0004 בהמות \u0003בתפיסת הבית,\u0004 בירושת אביהם, ייפטרו ממעשר בהמה? \u0003תלמוד לומר: \"יהיה\",\u0004 לרבות, וללמד שחייבים במעשר.","ותמהים: \u0003והאי\u0004 \u0005[ו\u0006הרי פסוק \u0005זה]\u0006 \u0003בבכור כתיב\u0004 \u0005[נאמר],\u0006 ולא במעשר! ומשיבים: \u0003אם אינו ענין לבכור, דהא איתיה\u0004 \u0005[שהרי ישנו]\u0006 \u0003בשותפות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובכורות בקרכם וצאנכם\"\u0004 (דברים יב, ו), בלשון רבים — \u0003תנהו ענין למעשר בהמה,\u0004 שבעלות משותפת פוטרת ממעשר.","שנינו במשנתנו: חלקו וחזרו ונשתתפו — חייבין בקלבון, ופטורין ממעשר בהמה. \u0003אמר ר' ירמיה: פעמים שחייבין\u0004 האחים והשותפים שחלקו וחזרו ונשתתפו, \u0003בזה ובזה, ופעמים שפטורין מזה ומזה, פעמים שחייבין בקלבון ופטורין ממעשר בהמה, ופעמים שחייבין במעשר בהמה ופטורין מן הקלבון.\u0004","ומסבירים: \u0003חייבין בזה ובזה\u0004 — במקרה \u0003שחלקו בכספים,\u0004 וחזרו והשתתפו בהם, וחייבים בקלבון, כדין שותפים, \u0003ולא חלקו בבהמה,\u0004 אלא נשארה בתפוסת הבית, ולכן היא חייבת במעשר. \u0003פטורין מזה ומזה\u0004 — \u0003שחלקו בבהמה,\u0004 וחזרו ונשתתפו, ודינם כשותפים שפטורים ממעשר בהמה, \u0003ולא חלקו בכספים,\u0004 והשקלים שניתנו עבור שניהם ניתנו מתפוסת הבית.","\u0003חייבין בקלבון ופטורין ממעשר בהמה\u0004 — \u0003שחלקו\u0004 ונשתתפו \u0003בזה ובזה.\u0004","\u0003חייבין במעשר בהמה ופטורין מן הקלבון\u0004 — \u0003שלא חלקו\u0004 לא \u0003בזה ו\u0004לא \u0003בזה.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ומה החידוש שבדברי ר' ירמיה? ומשיבים: במקרה ש\u0003חלקו בבהמה ולא חלקו בכספים איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005]\u0006 שפטורים בזה ובזה, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון\u0004 ש\u0003חלקו בבהמה\u0004 — \u0003גלו דעתייהו דלמיפלג קיימי\u0004 \u0005[גילו דעתם שלחלוק\u0006 גם בכספים \u0005הם עומדים],\u0006 \u0003ו\u0004אם כן \u0003ליחייבו\u0004 \u0005[שיהיו חייבים]\u0006 \u0003בקלבון,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שכל עוד לא חלקו בכספים — אינם חייבים בקלבון.","\u0003אמר רב ענן: לא שנו,\u0004 שאם חלקו וחזרו ונשתתפו פטורים, כדין שותפים רגילים, \u0003אלא\u0004 במקרה \u0003שחלקו\u0004 מתחילה \u0003גדיים כנגד תיישים ותיישים כנגד גדיים,\u0004 כלומר, שלא חילקו את התיישים בשווה ואת הגדיים בשווה, אלא חילקו באופן כללי את הבהמות לפי שוויין. והרי זה כאילו קנו זה מזה, וכשהם חוזרים ומשתתפים — הרי זה כשני זרים שנשתתפו ביניהם.","\u0003אבל\u0004 אם \u0003חלקו\u0004 מתחילה \u0003גדיים כנגד גדיים ותיישים כנגד תיישים\u0004 — \u0003אומר\u0004 אני כי \"יש ברירה\", כלומר, אנו מניחים ש\u0003זה,\u0004 כל אחד מהם, נתברר \u0003חלקו המגיעו משעה ראשונה לכך,\u0004 ואם חזרו ונשתתפו — נחשב הדבר כאילו לא חלקו מעולם, וחייבים במעשר.","\u0003ורב נחמן אמר: אפילו חלקו גדיים כנגד גדיים ותיישים כנגד תיישים\u0004 — \u0003אין אומרים\u0004 כי \u0003זה הוא חלקו המגיעו משעה ראשונה לכך,\u0004 ובכל מקרה כשחזרו ונשתתפו — דינם כשותפים רגילים, הפטורים ממעשר בהמה.","\u0003ו\u0004כן נחלקו אמוראים אחרים בשאלה זו, ש\u0003ר' אלעזר אמר: לא שנו\u0004 שאם נשתתפו — פטורים כדין שותפים, \u0003אלא\u0004 רק במקרה \u0003שחלקו\u0004 מתחילה \u0003תשעה\u0004 גדולים \u0003כנגד עשרה\u0004 קטנים, או \u0003עשרה כנגד תשעה,\u0004 מפני שעל ידי השומא של תשעה גדולים כנגד עשרה קטנים, נחשב הדבר כאילו קנו זה מזה.","\u0003אבל חלקו תשעה כנגד תשעה ועשרה כנגד עשרה\u0004 — \u0003אומר\u0004 אני: \u0003זה\u0004 הוא \u0003חלקו המגיעו משעה ראשונה לכך,\u0004 וכשחזרו ונשתתפו — נחשב הדבר כאילו לא חלקו מעולם, והם חייבים במעשר בהמה.","\u0003ור' יוחנן אמר: אפילו חלקו תשעה כנגד תשעה, ועשרה כנגד עשרה, אין אומר\u0004 אני: \u0003זה חלקו המגיעו משעה ראשונה לכך,\u0004 ובכל מקרה פטורים ממעשר בהמה."],["ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין זה, שאין אומרים בחלוקת ירושה, ש\"יש ברירה\" וכל אחד מן האחים זכה בחלקו הראוי לו מתחילה. ש\u0003אמר ר' אסי אמר ר' יוחנן: האחין שחלקו\u0004 בינם את ירושת אביהם — \u0003לקוחות הן,\u0004 כאילו קנו זה מזה את חלקם, \u0003ו\u0004לכן \u0003מחזירין זה לזה ביובל\u0004 את השדות שקיבלו.","ואין אומרים \"יש ברירה\", שמתברר למפרע שכל אחד קיבל את חלקו הראוי לו מתחילה בירושת אביו, ומעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 שני הדברים להיאמר, \u0003דאי אשמעינן הכא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005כאן],\u0006 במעשר בהמה, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' יוחנן\u0004 שאין מניחים שכל אחד זכה בטלאים שלו, משום שמעשר בהמה הוקש לבכור, שנאמר: \"בכור בניך תתן לי כן תעשה לשורך לצאנך\" (שמות כב, כח), ואם הריהו \u0003דומיא\u0004 \u0005[בדומה]\u0006 לבכור \u0003בנך,\u0004 יש לומר: \u0003מה\u0004 בכור \u0003בנך\u0004 — בברור לך, שהוא בודאי שלך, ולא קנוי מאחר, \u0003אף\u0004 מעשר \u0003שורך וצאנך\u0004 — \u0003בברור לך,\u0004 ושלא יהיה בו שום צד של קנין. \u0003אבל שדה\u0004 הייתי אומר שדוקא \u0003מכר הוא דאמר רחמנא ליהדר\u0004 \u0005[שאמרה התורה שיחזור]\u0006 \u0003ביובל,\u0004 אבל \u0003ירושה\u0004 שחלקו האחים \u0003ומתנה לא\u0004 חוזרות. ולכן הוצרך להשמיענו שגם חלוקת ירושה דומה למכר, וחוזרת.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003שדה\u0004 שחלקו האחים, שהיא חוזרת ביובל, הייתי אומר שהיה מסופק האם חלוקה נחשבת למיקח, ולכן פסק \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 שיחזירו, כדין לקוחות. אבל לענין מעשר בהמה, אם נדון אותם כלקוחות — הריהם פטורים מן המעשר, ובזה יש לומר שהוא מחמיר, ואינו נותן להם דין לקוחות. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 הייתי אומר כי דוקא לגבי שדה מחזירים זה לזה כדין לקוחות, שהרי ביובל צריכות השדות לחזור \u0003ל\u0004כפי שהיו ב\u0003תחילה, אבל הכא\u0004 \u0005[כאן],\u0006 בחלוקת בהמות משותפות, שאין צורך בהחזרת המצב לקדמותו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 היה רואה אותם כלקוחות, אלא פוסק ש\"יש ברירה\", ומחייבם לעשר, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 היה לומר דבריו גם בזה וגם בזה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסוברים ש\"יש ברירה\" ממה ששנינו: \u0003וכן השותפין שחלקו, אחד נטל עשרה\u0004 טלאים \u0003ואחד נטל תשעה\u0004 טלאים \u0003וכלב\u0004 — העשרה \u0003שכנגד הכלב אסורין\u0004 בהקרבה על המזבח, מפני שהן נחשבים ל\"מחיר כלב\" (דברים כג, יט), שהרי ניתנו תמורתו, ואילו התשעה \u0003שעם הכלב\u0004 — \u0003מותרים. ואם אמרת\u0004 \u0005[אתה אומר]\u0006 כי \u0003\"יש ברירה\"\u0004 — \u0003ליברור חד מינייהו לבהדי\u0004 \u0005[שיבחר אחד מהם כנגד]\u0006 ה\u0003כלב, ולשקול\u0004 \u0005[ויטול אותו]\u0006 שהרי נתברר שהוא מחיר הכלב, \u0003והנך לישתרו\u0004 \u0005[ואלה\u0006 הנשארים \u0005יותרו\u0006 למזבח\u0005]!\u0006","\u0003אמר רב אשי: אי דשוו כולהו להדדי\u0004 \u0005[אם\u0006 במקרה \u0005ששווים כולם זה לזה]\u0006 במחירם, וגם הכלב שווה כטלה — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר לעשות. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה \u0003דלא שוו כולהו להדדי\u0004 \u0005[שאינם שווים כולם זה לזה],\u0006 \u0003ושוי האי כלבא חד\u0004 \u0005[ושווה כלב זה\u0006 כ\u0005אחד]\u0006 \u0003ומשהו\u0004 מן הטלאים שכנגדו, \u0003והאי\u0004 \u0005[ואותו]\u0006 \u0003משהו\u0004 העודף על שווי טלה אחד \u0003משיך ואתי בכולהו\u0004 \u0005[נמשך ובא בכולם],\u0006 בכל אלו שכנגדו, ולכן אי אפשר ליחד טלה אחד כנגד הכלב, ולומר שהוברר שהוא האסור.","\u0003הכל,\u0004 כל הבהמות, \u0003נכנסין לדיר להתעשר, חוץ מן כלאים,\u0004 כגון הנולד מתייש וכבשה, \u0003וטרפה, ויוצא דופן,\u0004 שחתכו את דופן אמו והוציאוהו, \u0003ומחוסר זמן,\u0004 כלומר, פחות מבן שבוע שעדיין אסור בהקרבה, \u0003והיתום. ואיזהו יתום? כל שמתה אמה\u0004 או \u0003שנשחטה\u0004 בשעת הלידה \u0003ואחר כך ילדה,\u0004 כלומר, נגמרה הלידה. \u0003ר' יהושע אומר: אפילו\u0004 כבר \u0003נשחטה אמה והשלח\u0004 העור של האם \u0003קיים\u0004 בשעת הלידה — \u0003אין זה יתום.\u0004","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שאלו ששנינו במשנה פסולים למעשר? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר לגבי דיני קרבנות בכלל: \"שור או כשב או עז כי יולד והיה שבעת ימים תחת אמו ומיום השמיני והלאה ירצה לקרבן\" וגו' (ויקרא כב, כז). ומלשון הכתוב \u0003\"שור או כשב\"\u0004 למדו חכמים שיהיה שור או כבש מוגדר וברור לעצמו — \u0003פרט לכלאים\u0004 שנולד משני מינים, שאינו ראוי להקרבה. \u0003\"או עז\",\u0004 שיהיה עז גמורה — \u0003פרט\u0004 לנדמה, שהוא דומה לעז, אלא שאמו רחל. \u0003\"כי יולד\"\u0004 — \u0003פרט ליוצא דופן,\u0004 שאין זו לידה. \u0003\"והיה שבעת ימים\"\u0004 — \u0003פרט למחוסר זמן,\u0004 כלומר, קודם שעברו עליו שבעה ימים. \u0003\"תחת אמו\"\u0004 — פרט ליתום, שלא היה תחת אמו, שמתה קודם שנולד. ומנין שדברים אלו נוגעים גם למעשר? \u0003ר'\u0004","\u0003ישמעאל בנו של ר' יוחנן בן ברוקה אומר:\u0004 נלמד הדבר בגזירה שווה, \u0003נאמר כאן\u0004 במעשר: \"כל אשר יעבור \u0003תחת השבט\u0004 העשירי יהיה קדש\" (ויקרא כז, לב), \u0003ונאמר להלן\u0004 בשאר קדשים: \u0003\"תחת אמו\", מה להלן\u0004 — \u0003פרט לכל השמות הללו,\u0004 לכלאים וכו', \u0003אף כאן\u0004 במעשר בהמה — \u0003פרט לכל השמות הללו.\u0004 ומן הצד השני: \u0003ומה כאן,\u0004 במעשר בהמה — \u0003פרט לטרפה,\u0004 מפני שנאמר: \"כל אשר יעבור תחת השבט\", וטריפה אינה עוברת תחת השבט, שאין אדם מונה טריפה, \u0003אף להלן,\u0004 בשאר קדשים — \u0003פרט לטרפה.\u0004","ושואלים: \u0003\"הכל\u0004 נכנסין לדיר להתעשר\", ששנינו במשנתנו, \u0003לאיתויי מאי\u0004 \u0005[להביא את מה]?\u0006 ואומרים: \u0003לאיתויי הא דתנו רבנן\u0004 \u0005[להביא את זו ששנו חכמים]:\u0006 \u0003הרובע\u0004 את האישה, \u0003והנרבע\u0004 לאיש, \u0003והמוקצה\u0004 לצורך עבודה זרה, \u0003והנעבד\u0004 שעבדו בו עבודה זרה, \u0003והאתנן\u0004 ששימש לאתנן זונה, \u0003והמחיר,\u0004 ששימש כמחיר לכלב, \u0003וטומטום,\u0004 שאין לו סימני זכר ונקבה, \u0003ואנדרוגינוס,\u0004 שיש לו גם סימני זכר וגם סימני נקבה — \u0003כולן נכנסין לדיר להתעשר,\u0004 אף על פי שהם פסולים למזבח. \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: טומטום ואנדרוגינוס אין נכנסין לדיר להתעשר.\u0004","ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא\u0006 של המשנה \u0005שלנו],\u0006 \u0003אי גמר\u0004 \u0005[אם\u0006 הוא \u0005למד]\u0006 בגזירה שווה \u0003\"תחת\" \"תחת\" מ\u0004שאר \u0003קדשים\u0004 — \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003לא\u0004 יתעשרו, שהרי הם פסולים בשאר קדשים, \u0003ואי לא יליף\u0004 \u0005[ואם אינו למד]\u0006 — \u0003הני מנא ליה\u0004 \u0005[אלה\u0006 שפסל למעשר, כלאים, טריפה וכו', \u0005מנין לו]?\u0006","ומשיבים: \u0003לעולם גמיר\u0004 \u0005[למד]\u0006 גזירה שווה, לפסול ממעשר את הפסולים למזבח, \u0003והני רחמנא רבינהו\u0004 \u0005[ואלה התורה ריבתה אותם],\u0006 שיתעשרו, למרות שאינם ראויים למזבח. ומנין שנתרבו? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי הפסולים לקרבן: \u0003\"כי משחתם בהם מום בם לא ירצו לכם\"\u0004 (ויקרא כב, כה), \u0003ו\u0004בפירוש המלה \"משחתם\" \u0003תאנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל מקום\u0004 בכתוב \u0003שנאמר בו\u0004 לשון \u0003השחתה אינו אלא דבר ערוה ועבודה זרה;\u0004","\u0003דבר ערוה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי השחית כל בשר את דרכו על הארץ\"\u0004 (בראשית ו, יב), \u0003עבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פן תשחיתון ועשיתם לכם פסל תמונת כל סמל תבנית זכר או נקבה\"\u0004 (דברים ד, טז).","\u0003ו\u0004ממה שהקיש הכתוב את \"משחתם בהם\" ל\"מום בם\" יש ללמוד כי \u0003כל שהמום פוסל בו\u0004 — גם \u0003דבר ערוה ועבודה זרה פוסלין בו, וכל שאין המום פוסל בו\u0004 — \u0003אין דבר ערוה ועבודה זרה פוסלין בו. והאי\u0004 \u0005[וזה]\u0006 \u0003מעשר, הואיל ולא פסיל ביה מומא\u0004 \u0005[ואין פוסל בו המום]\u0006 מלהיכנס לדיר להתעשר, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"לא יבקר בין טוב לרע ולא ימירנו\"\u0004 (ויקרא כ״ז:ל״ג), על כן \u0003דבר ערוה ועבודה זרה נמי לא פסיל ביה\u0004 \u0005[גם כן אינו פוסל בו].\u0006","וכל אלו ששנינו בברייתא שהם מצטרפים למעשר, הריהם פסולים משום דבר ערוה או משום עבודה זרה: \u0003רובע ונרבע\u0004 הם \u0003דבר ערוה, מוקצה ונעבד\u0004 הם \u0003עבודה זרה, ואתנן\u0004 הוא \u0003דבר ערוה, ומחיר\u0004 כלב \u0003איתקש\u0004 \u0005[הוקש,\u0006 הושווה\u0005]\u0006 בכתוב \u0003לאתנן\u0004 (דברים כג, יט).","וביחס ל\u0003טומטום ואנדרוגינוס\u0004 שהם מצטרפים למעשר, למרות שאינם בכלל דבר ערוה ולא בכלל עבודה זרה — \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 טומטום ואנדרוגינוס \u0003ספיקא\u0004 \u0005[ספק]\u0006 זכר או נקבה הוא, וחייב לעשרם, שהרי בין זכר ובין נקבה מצטרפים למעשר בהמה.","ומה ששנינו, \u0003ר' שמעון בן יהודה אומר\u0004 משום ר' שמעון: טומטום ואנדרוגינוס אין נכנסין לדיר להתעשר, הרי זה משום ש\u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 אכן \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 אבל \u0003מיעט רחמנא גבי\u0004 \u0005[מיעטה התורה לגבי]\u0006 \u0003קדשים,\u0004 שרק \u0003זכר ודאי ונקבה ודאית\u0004 ראויים למזבח, \u0003ולא טומטום ואנדרוגינוס\u0004 שהם ספק, ולכן ל\u0003מעשר נמי\u0004 \u0005[גם כן]\u0006 הם פסולים, מפני שהוא \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"תחת\" \"תחת\" מקדשים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכל נכנסין לדיר להתעשר, חוץ מן הכלאים והטרפה,\u0004 אלו \u0003דברי ר' אלעזר בר' יהודה איש כפר ברתותא שאמר משום\u0004 (בשם) \u0003ר' יהושע. אמר ר' עקיבא: אני שמעתי הימנו\u0004 (ממנו), מר' יהושע, ש\u0003אף יוצא דופן ומחוסר זמן ויתום\u0004 אינם מתעשרים.","ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון\u0006 שבברייתא\u0005],\u0006 \u0003אי גמר\u0004 \u0005[אם הוא למד]\u0006 בגזירה שווה \u0003\"תחת\" \"תחת\" מקדשים\u0004 — \u0003הני\u0004 \u0005[אלה],\u0006 יוצא דופן ומחוסר זמן ויתום, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יתעשרו, שהרי הם פסולי מזבח. \u0003ואי לא גמר\u0004 \u0005[ואם לא למד],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003טרפה,\u0004 הריהי פטורה ממעשר, מפני ש\u0003\"כל אשר יעבר תחת השבט\"\u0004 (ויקרא כז, לב) \u0003כתיב\u0004 \u0005[נאמר], והרי זה\u0006 \u0003פרט לטרפה שאינה עוברת\u0004 תחת השבט, \u0003אלא כלאים מנא ליה\u0004 \u0005[מנין לו]\u0006 למעט ממעשר?","ומשיבים: \u0003לעולם גמר\u0004 \u0005[למד]\u0006 גזירה שווה זו מקדשים, ולכן הוא ממעט כלאים וטריפה ממעשר, \u0003ו\u0004אולם \u0003ביוצא דופן\u0004"],["\u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003אמר: יוצא דופן ולד מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא\u0004 באדם, לטמא את אמו טומאת לידה, וכן בבהמה — לענין קדשים, וממילא חייב במעשר בגזירה שווה מקדשים. \u0003ו\u0004ש\u0003לא כ\u0004דעת \u0003ר' יוחנן,\u0004 שאמר שר' שמעון מודה ביוצא דופן שאינו ראוי לקדשים, וממילא גם אינו מתעשר.","\u0003במחוסר זמן סבר לה\u0004 \u0005[סבור הוא]\u0006 התנא הראשון בברייתא, \u0003כ\u0004דעת \u0003ר' שמעון בן יהודה, ש\u0004מחייבו במעשר. ומה שאינו פוסל \u0003יתום\u0004 — הרי זה \u0003כגון שהשלח,\u0004 עור אמו, \u0003קיים. ור' יהושע לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 במשנתנו: \u0003אפילו שחט את אמו והשלח קיים\u0004 בשעה שנולד — \u0003אין זה יתום.\u0004","ובענין זה מסופר, \u0003העיד\u0004 \u0003ר' ישמעאל בן סתריאל מ\u0004המקום \u0003ערקת לבינה לפני רבי: במקומנו מפשיטין את ה\u0004בהמה ש\u0003מתה\u0004 בלידתה \u0003ומלבישין\u0004 בעורה \u0003את\u0004 הולד \u0003החי\u0004 כדי לשמור עליו. \u0003אמר רבי: נתגלה טעמא\u0004 \u0005[הטעם]\u0006 \u0005של משנתינו, השלח שהוזכר במשנה, שאותו שלח מהווה תחליף לאמו. ועוד העיד ר' ישמעאל בן סתריאל:\u0006","\u0003חזירין\u0004 מיני חזרת (חסה) \u0003שבמקומנו יש להם ששים רבוא קלפים\u0004 (עלים) \u0003בבית המסס\u0004 (בקיבה) \u0003שלו.\u0004 ועוד העיד: \u0003פעם אחת נפל ארז אחד שבמקומנו, ועברו שש עשרה קרונות על חודו\u0004 של גבו כ\u0003אחת,\u0004 זה בצד זה.","\u0003פעם אחת נפלה ביצת בר יוכני,\u0004 שהוא עוף ענק, \u0003וטבעה ששים כרכים\u0004 במה שנשפך ממנה, \u0003ושברה שלש מאות ארזים.\u0004 ושואלים: \u0003ומי שדיא ליה\u0004 \u0005[והאם\u0006 היא \u0005זורקת אותה]\u0006 את ביצתה? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"כנף רננים נעלסה\u0004 כי תעזוב לארץ ביציה\" (איוב לט, יג—יד), ולפי חכמים מדובר על בר יוכני, המניח בנחת את ביצתו על הארץ! \u0003אמר רב אשי: ההוא מוזרתא הואי\u0004 \u0005[אותה\u0006 ביצה, ביצה \u0005מוזרת,\u0006 לא מופרית \u0005היתה],\u0006 ומכיוון שלא יצא ממנה אפרוח השליכה אותה.","\u0003שלש גרנות למעשר בהמה,\u0004 כלומר, שלוש פעמים בשנה צריך לאסוף את הבהמות שנולדו בין פעם לפעם כדי לעשרן: \u0003בפרס הפסח\u0004 (סמוך לפסח), ובפרס העצרת, ובפרס החג (חג הסוכות), אלו","\u0003דברי ר' עקיבא. בן עזאי אומר: בעשרים ותשעה באדר, באחד בסיון, בעשרים ותשעה באב. ר' אלעזר ור' שמעון אומרים: באחד בניסן, באחד בסיון, בעשרים ותשעה באלול. ולמה אמרו בעשרים ותשעה באלול ולא אמרו באחד בתשרי? מפני שהוא יום טוב\u0004 של ראש השנה, \u0003ואי אפשר לעשר ביום טוב, לפיכך הקדימוהו בעשרים ותשעה באלול.\u0004","\u0003ר' מאיר אומר: באחד באלול ראש השנה למעשר בהמה. בן עזאי אומר: האלולים,\u0004 כלומר, אלו שנולדו באלול \u0003מתעשרים בפני עצמן,\u0004 מפני שספק אם הלכה כר' מאיר, שבאחד באלול הוא ראש השנה למעשר בהמה, או כר' אלעזר ור' שמעון, הסבורים שאחד בתשרי הוא ראש השנה למעשר בהמה.","\u0003כל הנולדים מאחד בתשרי עד עשרים ותשעה באלול\u0004 באותה שנה — \u0003הרי אלו מצטרפין\u0004 לעשר מהם (כדעת ר' אלעזר ור' שמעון). \u0003חמשה\u0004 שנולדו \u0003לפני ראש השנה וחמשה\u0004 שנולדו \u0003לאחר ראש השנה\u0004 — \u0003אינן מצטרפין,\u0004 מפני שאין מעשרים משל שנה אחת על של שנה אחרת. \u0003חמשה\u0004 שנולדו \u0003לפני הגורן וחמשה לאחר הגורן\u0004 — \u0003הרי אלו מצטרפין. אם כן, למה נאמרו שלש גרנות למעשר בהמה?\u0004 לומר \u0003שעד שלא הגיע הגורן\u0004 — \u0003מותר למכור ולשחוט\u0004 מהן בלא לעשרן, \u0003הגיע הגורן\u0004 — \u0003לא ישחוט\u0004 מהן בלא לעשרן, \u0003ואם שחט\u0004 — \u0003פטור.\u0004","שנינו במשנתנו: שלוש גרנות למעשר בהמה. ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דוקא\u0005]\u0006 \u0003תלת\u0004 \u0005[שלוש\u0006 גרנות\u0005]?\u0006 \u0003אמר רבה בר שילא: לקבל\u0004 \u0005[כנגד]\u0006 \u0003חורפי ואפלי וקייטי\u0004 \u0005[המקדימות,\u0006 היולדות בחורף, \u0005והמאחרות\u0006 היולדות באביב, \u0005והקיציות\u0006 היולדות בקיץ\u0005].\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 מדוע דוקא\u0005]\u0006 \u0003בהני זימני\u0004 \u0005[בזמנים אלה],\u0006 בפרס הפסח, בפרס עצרת ובפרס החג? \u0003אמר ר' תנחום בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא איש כפר עכו\u0004"],["\u0003כדי שתהא בהמה מצויה לעולי רגלים,\u0004 מפני שאדם שוהה מלמכור את בהמותיו ומלשוחטן עד שיעשרן בזמנים אלו שקבעו חכמים.","\u0003ואף על גב דתנן\u0004 \u0005[ואף על פי ששנינו]\u0006 במשנתנו: \u0003עד שלא הגיע הגורן מותר למכור ולשחוט,\u0004 \u0003ניחא ליה\u0004 \u0005[נוח לו\u0006 לאדם\u0005]\u0006 \u0003דליתעביד מצוה בממוניה והדר לזבון וליכול\u0004 \u0005[שתיעשה מצוה בממונו,\u0006 לעשר את בהמותיו, \u0005ואחר כך ימכור ויאכל].\u0006","ושואלים: \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 התנא \u0003\"גורן\"\u0004 לזמן שתיקנו חכמים למעשר בהמה? ומשיבים: מפני \u0003דטבלה\u0004 \u0005[שהיא עושה טבל]\u0006 \u0003כגורן,\u0004 שמזמן זה אסור למכור ולשחוט הבהמות החדשות, כפי שאיסוף הדגן בגורן עושה אותו טבל, האסור באכילה עד שיתעשר.","ועוד שואלים: \u0003וכמה\u0004 הוא \u0003פרס\u0004 שלפני הרגל, שאז הוא זמן מעשר בהמה לדעת ר' עקיבא? \u0003פירש ר' יוסי בר' יהודה: אין פרס פחות מחמשה עשר יום.\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[כיצד נשמע,\u0006 נלמד הדבר\u0005]\u0006 מ\"פרס\"? \u0003אמר ר' אבהו: \"פרוס\"\u0004 משמעו \u0003פלגא\u0004 \u0005[חצי].\u0006 ושואלים: \u0003פלגא דמאי\u0004 \u0005[חצי של מה]\u0006 הוא חמישה עשר יום? ומשיבים: \u0003פלגא\u0004 \u0005[חצי]\u0006 של הזמן שבו דורשים ב\u0003הלכות פסח, כי הא דתניא\u0004 \u0005[כמו זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שואלין ודורשין בהלכות פסח קודם לפסח שלשים יום. רבן שמעון בן גמליאל אומר: שתי שבתות\u0004 (שבועות) מקדימים לדרוש קודם הפסח, ולא שלושים יום.","שנינו במשנה, \u0003בן עזאי אומר:\u0004 הגרנות למעשר בהמה הם \u0003בעשרים ותשעה באדר, באחד בסיון,\u0004 בעשרים ותשעה באב. ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים]\u0006 \u0003ר' עקיבא\u0004 שאמר: בפרס הפסח, כלומר, חמישה עשר יום קודם לפסח, \u0003ובן עזאי\u0004 שאמר: בעשרים ותשעה באדר? ומשיבים, \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003אדר הסמוך לניסן זימנין\u0004 \u0005[פעמים]\u0006 הוא חודש \u0003מלא,\u0004 בן שלושים יום, \u0003וזימנין\u0004 \u0005[ופעמים]\u0006 הוא חודש \u0003חסר,\u0004 בן עשרים ותשעה יום, וכך \u0003זימנין\u0004 \u0005[פעמים]\u0006 \u0003דמיקלע\u0004 \u0005[שמזדמן]\u0006 פרס הפסח \u0003ביום שלשים\u0004 באדר, \u0003וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003דמיקלע\u0004 \u0005[שמזדמן]\u0006 \u0003בעשרים ותשעה\u0004 באדר, \u0003ומשום הכי לא קביע ליה\u0004 \u0005[ומשום כך לא קבוע לו]\u0006 \u0003זמן,\u0004 תאריך בחודש. \u0003ובן עזאי סבר\u0004 \u0005[סבור]:\u0006 \u0003אדר הסמוך לניסן לעולם חסר, הילכך קביע ליה\u0004 \u0005[על כן קבוע לו]\u0006 \u0003זמן בעשרים ותשעה באדר.\u0004","מה שאמר בן עזאי שהגורן השני הוא \u0003באחד בסיון,\u0004 ולא חמישה עשר יום קודם עצרת, טעם הדבר הוא: \u0003איידי דלא נפישי\u0004 \u0005[מכיון שאין מרובות]\u0006 הבהמות שנולדות מאז הגורן הקודם, \u0003אי אמרת ליקדים ליעשר\u0004 \u0005[אם אומר אתה שיקדים ויעשר],\u0006 בחמישה עשר יום קודם העצרת, \u0003עד דמטי רגל שלמי להו\u0004 \u0005[עד שיגיע הרגל\u0006 יימכרו \u0005ויכלו להם]\u0006 ולא ייוותרו בהמות לעולי הרגל בעצרת.","ומה שאמר בן עזאי שהגורן השלישי הוא \u0003בעשרים ותשעה באב וכו',\u0004 ולא בחמישה עשר יום קודם חג הסוכות, הרי זה מפני ש\u0003בן עזאי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: האלולין מתעשרין בפני עצמן,\u0004 מספק האם ראש השנה למעשר בהמה הוא באחד באלול או באחד בתשרי, ולכן קבע את זמן הגורן לפני חודש אלול, כדי שלא יעשרו משל אב על של אלול ולהיפך, שהרי אין מעשרים מן הנולדים בשנה זו על הנולדים בשנה זו.","ושואלים: \u0003וליעשרינהו\u0004 \u0005[ושיעשר אותם]\u0006 \u0003ביום שלשים\u0004 באב! ומשיבים: \u0003זימנין דמחסרין ליה\u0004 \u0005[פעמים שמחסרים אותו]\u0006 את חודש \u0003אב,\u0004 ויום שלושים הוא למעשה אחד באלול, \u0003ובעינן למיעבד הכירא\u0004 \u0005[וצריכים אנו לעשות היכר],\u0006 כדי להבדיל בין \u0003חדש וישן,\u0004 שידעו אנשים שאין מעשרים מן הנולדים באב על הנולדים באלול ולהיפך.","שנינו במשנה, \u0003ר' אלעזר ור' שמעון אומרים:\u0004 הגרנות למעשר בהמה הם \u0003באחד בניסן, באחד בסיון,\u0004 בעשרים ותשעה באלול. ומסבירים: \u0003באחד בניסן\u0004 — \u0003כ\u0004דעת \u0003רבן שמעון בן גמליאל,\u0004 ש\u0003אמר: שתי שבתות\u0004 לפני הפסח דורשים בהלכותיו. וקבעו את הגורן הסמוך לפסח באותו זמן, כחלק מן ההכנות לפסח. באחד בסיון — \u0003כדאמרן\u0004 \u0005[כמו שאמרנו],\u0006 בטעמו של בן עזאי, שהסמיך גורן זה לעצרת, מפני שהבהמות שנולדו מאז הגורן הקודם אינן מרובות. \u0003בעשרים\u0004","\u0003ותשעה באלול\u0004 — \u0003ר' אלעזר ור' שמעון לטעמייהו\u0004 \u0005[לשיטתם],\u0006 \u0003דאמרי\u0004 \u0005[שהם אומרים]:\u0006 \u0003באחד בתשרי ראש השנה למעשר בהמה,\u0004 ואין מעשרים מהנולדים בתשרי על הנולדים לפני כן.","שנינו במשנתנו בהסבר טעמם: \u0003ולמה אמרו בעשרים ותשעה באלול ולא אמרו באחד בתשרי? מפני שהוא יום טוב\u0004 ואי אפשר לעשר ביום טוב. ומקשים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו מטעם אחר, \u0003דבעינן למעבד הכירא\u0004 \u0005[שצריכים אנו לעשות היכר]\u0006 בין \u0003חדש וישן,\u0004 בין בהמות של שנה זו לשל שנה אחרת, כדי שלא יטעו ויעשרו מזה על זה!","ומשיבים: \u0003חדא ועוד קאמר\u0004 \u0005[\u0006טעם \u0005אחד ועוד\u0006 טעם \u0005הוא אומר],\u0006 \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 — \u0003דבעינן למיעבד הכירא\u0004 \u0005[שצריכים לעשות היכר]\u0006 בין \u0003חדש וישן. ועוד\u0004 טעם — \u0003מפני שהוא יום טוב, ואי אפשר לעשר ביום טוב,\u0004 \u0003משום סקרתא\u0004 \u0005[סיקרא,\u0006 צבע אדום\u0005],\u0006 שהיו צובעים בו את היוצא עשירי, כמבואר במשנה הבאה (להלן עמוד ב), וצביעה אסורה ביום טוב.","שנינו במשנתנו: \u0003ר' מאיר אומר: באחד באלול ראש השנה למעשר בהמה. בן עזאי אמר:\u0004 האלולים, הנולדים בחודש אלול — מתעשרים בפני עצמן. ובהסבר דעה זו, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר בן עזאי: הואיל והללו,\u0004 ר' אלעזר ור' שמעון, \u0003אומרים כך,\u0004 שאחד בתשרי הוא ראש השנה למעשר בהמה, והאלולים שייכים לשנה הקודמת, \u0003והללו,\u0004 ר' מאיר, \u0003אומרים כך,\u0004 שאחד באלול הוא ראש השנה למעשר בהמה, והאלולים שייכים לשנה החדשה, ואין בידינו להכריע כמי הלכה — \u0003האלולין מתעשרין לעצמן.\u0004 ושואלים: ומדוע הוא אוחז בדרך זו?","\u0003וליחזי טעמיה דמאן מסתבר\u0004 \u0005[ויראה טעמו של מי מסתבר],\u0006 ויכריע כשיטתו! \u0003וכי תימא: לא מצי קאי אטעמייהו\u0004 \u0005[ואם תאמר: לא היה יכול לעמוד על טעמם,\u0006 דעתם\u0005]\u0006 ולהכריע, ולכן נהג כך — לא ייתכן שמשום כך עשה, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003בן עזאי אומר: כל חכמי ישראל דומין עלי כקליפת השום חוץ מן הקרח הזה,\u0004 מר' עקיבא!","\u0003אמר ר' יוחנן: מפי השמועה\u0004 (המסורת) \u0003אמרוה, מפי חגי זכריה ומלאכי,\u0004 שכל אחד טען שכך קיבל במסורת, ומפני שמחלוקתם היתה בשמועה — לא יכול היה להכריע מסברה.","ולגופם של דברי בן עזאי, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003באיזה צד\u0004 (כיצד) \u0003אמר בן עזאי האלולים מתעשרין לעצמן? נולדו לו חמשה\u0004 טלאים \u0003באב וחמשה באלול\u0004 — \u0003אין מצטרפין\u0004 זה לזה, \u0003חמשה באלול וחמשה בתשרי\u0004 — \u0003אין מצטרפין, חמשה בתשרי וחמשה באב\u0004 שאחריו — \u0003מצטרפין.\u0004","ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003כי היכי דמפסקי\u0004 \u0005[כמו שמפסיקות]\u0006 ה\u0003שנים,\u0004 כך \u0003מפסקי\u0004 \u0005[מפסיקים]\u0006 ה\u0003גרנות,\u0004 שקבעו חכמים במשנתנו למעשר בהמה, ואין מעשרים מהנולדים לפני הגורן על הנולדים אחריו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שהגורן אינו מפסיק.","\u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חמשה לפני ראש השנה וחמשה לאחר ראש השנה\u0004 — \u0003אין מצטרפין, חמשה לפני הגורן וחמשה לאחר הגורן\u0004 — \u0003הרי אלו מצטרפין.\u0004","\u0003אמר רבא: לדברי בן עזאי,\u0004 אם \u0003נולדו לו חמשה\u0004 טלאים \u0003באב, וחמשה באלול, וחמשה בתשרי\u0004 — \u0003כונסן\u0004 כולם יחד \u0003לדיר להתעשר,\u0004"],["\u0003ונוטל אחד מן האלולין\u0004 בתור מעשר, \u0003והשאר פטורין, ממה נפשך\u0004 \u0005[רצונך]\u0006 כלומר, מכל צד שתעיין בדבר, שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003באחד באלול ראש השנה\u0004 — הרי שהנולדים ב\u0003אלול ותשרי מצטרפין\u0004 לעשרה וחייבים, \u0003ו\u0004של \u0003אב פטורים,\u0004 מפני שהם שייכים לשנה הקודמת, ואין בהם עשרה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003באחד בתשרי ראש השנה\u0004 — הרי שהנולדים ב\u0003אב ואלול מצטרפין,\u0004 ושל \u0003תשרי פטורין\u0004 לגמרי.","\u0003מאי אמרת\u0004 \u0005[מה אתה אומר]:\u0006 אין החמישה של תשרי פטורים לגמרי, אלא \u0003ליצרפו\u0004 \u0005[שיצטרפו]\u0006 לאחר מכן עם אלו שייוולדו אחריהם \u0003לגורן אחר\u0004 ויעשרם — אי אפשר לצרפם ולעשר את התערובת — שמא כבר נפטרו מן המעשר, שהלא \u0003עשירי ודאי אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שיהיה קודש, \u0003ולא ספק.\u0004","ותמהים על דברי רבא: לפי הנימוקים הללו \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 שנוטל אחד מן האלולים, ומה חידש בדבריו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003לגזור\u0004 \u0005[נגזור]\u0006 שלא יטול אפילו אחד מן האלולים, \u0003דילמא אתי למישקל מהנך\u0004 \u0005[שמא יבוא ליטול\u0006 אחד \u0005מאלה]\u0006 שנולדו באב או בתשרי, ואם הוא פטור — נמצא שהוא מביא חולין לעזרה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין חוששים לכך.","\u0003באי זה צד\u0004 (כיצד) \u0003מעשרין? כונסן\u0004 את כל הבהמות החדשות \u0003לדיר, ועושה להם פתח קטן כדי שלא יהו שנים יכולין לצאת כאחת, ומונין: אחד, שנים, שלשה, ארבעה, חמשה, ששה, שבעה, שמונה, תשעה. והיוצא עשירי סוקר בסיקרא\u0004 (צובע אותו בצבע אדום), \u0003ואומר: \"הרי זה מעשר\".\u0004 ומכל מקום, גם אם \u0003לא סקרו בסיקרא, ו\u0004כן אם \u0003לא מנאן בשבט,\u0004 שלא ספר אותם באמצעות מקלו, ככתוב \"כל אשר יעבור תחת השבט העשירי יהיה קדש\" (ויקרא כז, לב), אלא רק בפיו, \u0003או שמנאן רבוצים או עומדים\u0004 בלא להעבירם — \u0003הרי אלו מתעשרין\u0004 בדיעבד.","אבל \u0003היה לו מאה\u0004 טלאים \u0003ונטל עשרה\u0004 מתוכם, או \u0003עשרה ונטל אחד\u0004 — \u0003אין זה מעשר,\u0004 מפני שלא מנאם בזה אחר זה עד העשירי. \u0003ר' יוסי בר' יהודה אומר:\u0004 הרי זה \u0003מעשר\u0004 גם כך. אם קודם שגמר לעשר את בהמותיו \u0003קפץ אחד מן המנויין,\u0004 אלה שכבר יצאו ונמנו, \u0003לתוכן\u0004 — \u0003הרי\u0004 כל \u0003אלו\u0004 שבפנים \u0003פטורין.\u0004 קפץ אחד \u0003מן המעושרין,\u0004 זה שנקבע כמעשר, \u0003לתוכן,\u0004 ונתערב בהם, וכל אחד מהם ספק קדוש — \u0003כולם ירעו עד שיסתאבו,\u0004 עד שיפול בהם מום, \u0003ו\u0004אחר כך \u0003יאכלו במומן לבעלים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003באי זה צד\u0004 (כיצד) \u0003מעשר\u0004 אדם את בהמותיו? כונסן לדיר, ועושה להם פתח קטן כדי שלא יהו שנים יכולין לצאת כאחד, ומשאירים את \u0003אימותיהם מבחוץ והם מבפנים, ו\u0004אמותיהן \u0003גועות,\u0004 \u0003ו\u0004הולדות \u0003יוצאות לקראת אמן.\u0004 ושואלים: ומדוע בדרך זו?","\u0003ולפקינהו אינהו\u0004 \u0005[ושיוציא אותם עצמם],\u0006 שידחוף אותם לעבר הפתח! ומשיבים: \"כל אשר \u0003יעבר\"\u0004 (ויקרא כז, לב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 מעצמו, \u0003ולא שיעבירוהו.\u0004","ושואלים: \u0003ולשדי להו ירקא וליפקו לותיה\u0004 \u0005[ושישליך להם ירק\u0006 בחוץ \u0005ושיצאו אליו]!\u0006 \u0003אמר רב הונא: גזירה\u0004 גזרו חכמים לעשות כן, \u0003משום לקוח\u0004 (קנוי) \u0003ומשום יתום,\u0004 שפטורים ממעשר בהמה (ראה לעיל נה,ב. נז,א), שהואיל ואין להם אם שיצאו לקראתה, לא יבואו לעשרם.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003\"כל אשר יעבר תחת\"\u0004 (ויקרא כז, לב) — \u0003פרט לטריפה שאינה עוברת,\u0004 שאין אדם מונה טריפה, ואינה מצטרפת למעשר. \u0003\"תחת השבט\"\u0004 — מכאן ש\u0003מצוה למנותן בשבט. לא מנאן בשבט, או שמנאן\u0004 כשהם \u0003רבוצים או עומדים, מנין\u0004 שאף על פי כן חלה קדושה על העשירי? \u0003תלמוד לומר: \"העשירי קדש\"\u0004 (ויקרא כז, לב) — \u0003מכל מקום,\u0004 כל שהוא עשירי, למרות שלא עבר תחת השבט.","\u0003ואין לי אלא שקרא שמו \"עשירי\", לא קרא שמו \"עשירי\" מנין\u0004 שהוא קדוש מאליו? \u0003תלמוד לומר: \"יהיה קדש\"\u0004 (ויקרא כז, לב) — \u0003מכל מקום. יכול היו לו מאה ונטל עשרה, עשרה ונטל אחד,\u0004 מבלי למנות, \u0003יכול יהיו מעושרין? תלמוד לומר:\u0004 \"ה \u0003עשירי\"\u0004 — \u0003ואין זה עשירי. ר' יוסי בר' יהודה אומר:\u0004 גם זה \u0003מעשר,\u0004 למרות שלא מנאו.","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוסי בר' יהודה?\u0004 ומשיבים: \u0003סבר ליה\u0004 \u0005[סבור הוא]\u0006 \u0003כאבא אלעזר בן גומל, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא אלעזר בן גומל אומר:\u0004 נאמר ללויים בענין תרומת מעשר \u0003\"ונחשב לכם תרומתכם\u0004 כדגן מן הגורן\" (במדבר יח, כז) — \u0003בשתי תרומות הכתוב מדבר, אחת תרומה גדולה,\u0004 שנותן ישראל לכהן (\"כדגן מן הגורן\"), \u0003ואחת תרומת מעשר\u0004 (\"תרומתכם\"), שמן המעשר הראשון שקיבל הלוי מישראל תורם הלוי מעשר לכהן,","\u0003כשם שהתרומה גדולה ניטלת\u0004 מן הדגן \u0003באומד,\u0004 ואינו צריך למדוד כמות מסויימת, שהרי לא נקבע לה שיעור בתורה, \u0003ובמחשבה,\u0004 שאם אמר בליבו שחלק מסויים יהיה לתרומה, חלה עליו קדושה גם בלא אמירה —"],["\u0003אף תרומת מעשר,\u0004 למרות שהתורה נתנה לה שיעור מוגדר, מעשר מן המעשר — הריהי \u0003נטלת באומד ובמחשבה. ו\u0004לשיטת אבא אלעזר בן גומל אף \u0003מעשר\u0004 ראשון ניטל באומד ובמחשבה, שהרי \u0003קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 \u0003\"תרומה\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי את מעשר בני ישראל אשר ירימו לה' תרומה נתתי ללוים לנחלה\"\u0004 (במדבר יח, כד). והואיל \u0003ואיתקש\u0004 \u0005[והוקש]\u0006 בכתוב \u0003מעשר בהמה למעשר דגן,\u0004 אומרים אנו: \u0003מה מעשר דגן ניטל באומד ובמחשבה\u0004 — \u0003אף מעשר בהמה ניטל באומד ובמחשבה.\u0004 ולכן אמר ר' יוסי בן יהודה במשנתנו שמעשר בהמה חל גם בלא מנייה של הבהמות.","\u0003אמר רבא:\u0004 אם מנה תשעה ונותר רק ה\u0003עשירי\u0004 בדיר — \u0003מאליו הוא קדוש,\u0004 גם בלא שיוציאנו ויקרא לו בשם \"עשירי\". ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לרבא הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אילימא מהא דתניא\u0004 \u0005[אם תאמר מזו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003אין לי אלא שקרא שמו \"עשירי\", לא קרא שמו \"עשירי\" מנין? תלמוד לומר:\u0004 \"ה \u0003עשירי יהיה קדש\"\u0004 (ויקרא כז, לב) \u0003מכל מקום\u0004 — אין מכאן ראיה,","\u0003ודלמא\u0004 \u0005[ושמא]\u0006 מדובר בברייתא ש\u0003\"עשירי\" הוא דלא קרייה\u0004 \u0005[שלא קרא אותו],\u0006 אבל \u0003\"קדש\" קרייה\u0004 \u0005[קרא אותו],\u0006 אך מאליו אינו קדוש! ואומרים, \u0003אלא\u0004 למדו \u0003מהא\u0004 \u0005[מזו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קרא לתשיעי\u0004 בטעות \u0003\"עשירי\", ויצא העשירי ולא דבר,\u0004 לא אמר דבר — \u0003התשיעי\u0004 אינו קדוש ליקרב על המזבח. ואולם, מכיון שקרא לו \"עשירי\" יש בו צד של קדושה, ולכן \u0003נאכל במומו,\u0004 שאסור לשוחטו עד שיפול בו מום, \u0003והעשירי\u0004 הוא \u0003מעשר.\u0004","גם ראיה זו דוחים: \u0003ודלמא שאני התם דאיברר ליה עשירי\u0004 \u0005[ושמא שונה שם\u0006 הדין, מפני \u0005שהתברר לו עשירי],\u0006 שהרי יצא עשירי מהדיר. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 מדובר כשלא דיבר, אלא \u0003דאחוי עילויה\u0004 \u0005[שהצביע עליו]\u0006 כשעבר עשירי, ומשום כך העשירי קדוש, אבל אם נשאר בדיר — שמא אינו קדוש מאליו!","ואומרים: \u0003אלא מהא\u0004 \u0005[מזו]\u0006 אפשר להביא ראיה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קרא לתשיעי\u0004 בטעות \u0003\"עשירי\", ומת עשירי\u0004 כשהיה \u0003בדיר\u0004 — \u0003תשיעי נאכל במומו, וכולם פטורין. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003כולם פטורין, לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דקדש ליה\u0004 \u0005[ש\u0006כבר \u0005התקדש לו]\u0006 \u0003עשירי\u0004 מעצמו?","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 פטורים משום \u0003דאיפטרו\u0004 \u0005[שנפטרו]\u0006 \u0003במנין הראוי,\u0004 שבשעה שהעבירם בפתח, קודם שמת העשירי, היו ראויים להתעשר. \u0003דהאמר\u0004 \u0005[שהרי אמר]\u0006 \u0003רבא\u0004 עצמו: \u0003מנין הראוי פוטר!\u0004","ואומרים: \u0003אלא\u0004 הראיה היא \u0003מהא\u0004 \u0005[מזו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 \u0005ברייתא\u0006\u0005]:\u0006 \u0003קרא לתשיעי \"עשירי\", ונשתייר עשירי בדיר\u0004 — \u0003התשיעי נאכל במומו, והעשירי מעשר,\u0004 למרות שלא יצא ולא קרא לו שם. ולגופה של ברייתא זו, ששנינו בה שהתשיעי קדוש ונאכל במומו, מקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 שבמקרה כזה ה\u0003תשיעי חולין!\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב ששת: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו שיטת מי היא]?\u0006 שיטת \u0003ר' שמעון בן יהודה היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004"],["\u0003אף התשיעי\u0004 שקרא לו \"עשירי\" \u0003אינו קדוש\u0004 ליאכל במומו, \u0003אלא אם כן נעקר שם עשירי הימנו\u0004 (ממנו), מן העשירי, כלומר, שטעה וקרא לעשירי בשם \"תשיעי\". \u0003והדין נותן\u0004 שכן הוא:","\u0003ומה אחד עשר שהוא עושה קדושה\u0004 חמורה \u0003ליקרב\u0004 קרבן שלמים (ראה במשנה להן ס,א), \u0003אינו קדוש\u0004 כשקרא לו \"עשירי\", \u0003אלא אם כן נעקר שם עשירי הימנו\u0004 (מן העשירי), \u0003תשיעי ש\u0004אם קרא לו \"עשירי\" \u0003אין עושה קדושה ליקרב,\u0004 אלא רק קדושה קלה, שאסור לאוכלו בלא מום — \u0003אינו דין ש\u0004רק \u0003אם נעקר שם עשירי הימנו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 קדוש כשקרא לו \"עשירי\", \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 קדוש?","ודוחים את הטענה: הבחנה זו עצמה שבין דין התשיעי ודין האחד עשר, \u0003היא הנותנת,\u0004 מוכיחה להיפך: \u0003אחד עשר שהוא עושה קדושה\u0004 חמורה \u0003ליקרב,\u0004 דוקא \u0003אי\u0004 \u0005[אם]\u0006 \u0003נעקר שם עשירי הימנו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חלה הקדושה על האחד עשר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 חלה. אבל \u0003תשיעי, שאינו עושה קדושה ליקרב,\u0004 אלא רק לאוכלו במומו, יש בכוח קדושה קלה זו לחול \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא נעקר שם עשירי הימנו.\u0004","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 יש טעם אחר להבחין ביניהם: לגבי ה\u0003אחד עשר, דאיברר ליה\u0004 \u0005[ש\u0006כבר \u0005התברר לו]\u0006 ה\u0003עשירי,\u0004 שכבר יצא, רק \u0003אי\u0004 \u0005[אם]\u0006 \u0003נעקר שם עשירי הימנו\u0004 מן העשירי עצמו — \u0003אין\u0004 \u0005[כן],\u0006 חלה קדושה על האחד עשר, אבל \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 נעקר שם העשירי ממנו — \u0003לא\u0004 חלה קדושה על האחד עשר.","אבל ב\u0003תשיעי, דאכתי לא איברר ליה\u0004 \u0005[שעדיין לא התברר לו]\u0006 מיהו ה\u0003עשירי,\u0004 שהרי עדיין לא יצא העשירי, אם טעה וקרא לתשיעי בשם \"עשירי\" — חלה קדושה על התשיעי, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שאחר כך \u0003לא נעקר שם עשירי הימנו,\u0004 מן העשירי. ומוסיפים: \u0003תו לא מידי\u0004 \u0005[ושוב אין\u0006 להקשות \u0005דבר]\u0006 על טענות אלו, ונדחו דברי ר' שמעון בן יהודה משום ר' שמעון.","\u0003אמר רבא: מנין הראוי פוטר,\u0004 שכל טלה שנמנה למעשר בשעה שהיה בדיר מספר ראוי של טלאים — נפטר מן המעשר, גם אם לא נתקדש העשירי, וכגון שמת. ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לרבא הא\u0004 \u0005[\u0006הלכה \u0005זו]?\u0006 \u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003קפץ אחד מן המנויין,\u0004 שכבר יצאו בפתח, \u0003לתוכן,\u0004 לתוך אלו שבתוך הדיר — \u0003כולן פטורין,\u0004 מפני שכל אחד הוא ספק מנוי כבר. ויש לשאול: \u0003מנויין גופייהו דאיפטרו\u0004 \u0005[עצמם שנפטרו],\u0006 במה הם נפטרו? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003במנין הראוי,\u0004 מפני שהיו ראויים להתעשר?","ודוחים: \u0003ודלמא דעשר עילוייהו\u0004 \u0005[ושמא\u0006 מדובר \u0005שעישר עליהם],\u0006 כלומר, שיצא גם עשירי והתקדש, ובגללו נפטרו!","ומשיבים: \u0003ההיא לא מצית אמרת\u0004 \u0005[\u0006תשובה \u0005זו אינך יכול לומר],\u0006 \u0003הא תני\u0004 \u0005[\u0006ש\u0005הרי שנה]\u0006 לאחר מכן דין זה: קפץ אחד \u0003מן המעושרין לתוכן!\u0004","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מעושרין\"? מעשר דוקא,\u0004 כלומר, בהמות שנתקדשו כמעשר. ומסייעים לכך: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר, ממה \u0003דקתני\u0004 \u0005[שהוא שונה\u0006 בדינם\u0005]:\u0006 כולם \u0003ירעו\u0004 עד שיפול בהם מום, ורק אז ייאכלו כדין מעשר, מפני שכולם ספק מעשר! ונמצא שאי אפשר להוכיח ש\"המנויין\" ששנינו במשנתנו נפטרו בגלל מנין הראוי.","\u0003אלא אמר רבא:\u0004 מכאן יש ראיה שמנין הראוי פוטר, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כל אשר יעבור תחת השבט העשירי יהיה קודש\" (ויקרא כז, לב), ויש לדייק: \u0003\"יעבר\"\u0004 — \u0003ולא שכבר עבר.\u0004 ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שכבר עבר\"? אי דעשר עילוייהו\u0004 \u0005[אם ש\u0006כבר \u0005עישר עליהם],\u0006 שהוציא עשירי אחריהם — \u0003צריכא למימרא\u0004 \u0005[צריך\u0006 הדבר הזה \u0005להיאמר],\u0006 שאין מעבירם לעשרם בשנית? \u0003אלא לאו דאיפטרו להו\u0004 \u0005[האם לא\u0006 מדובר \u0005שנפטרו להם]\u0006 בלא שיצא עשירי אחריהם, אלא \u0003ב\u0004עצם \u0003מנין הראוי. שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של רבא: היו לו עשרה טלאים והכניסן לדיר, ומנה חמשה, ומת אחד מהם; אם אחד \u0003מן המנויים\u0004 כבר \u0003מת\u0004 — \u0003מונה ומשלים עליהם\u0004 עד העשירי ומקדשו, \u0003אם\u0004 אחד \u0003משאינן מנויים\u0004 עדיין \u0003מת\u0004 — ה\u0003מנויים\u0004 כבר \u0003פטורין\u0004 במנין הראוי, \u0003ושאינן מנויים\u0004 עדיין, שהיו בפנים — נאסר לאוכלם ולמוכרם בלא מעשר, ו\u0003מצטרפין\u0004 עם טלאים אחרים \u0003ל\u0004התעשר ב\u0003גורן אחר.\u0004","\u0003ו\u0004באותו ענין \u0003אמר רבא: היו לו ארבעה עשר טלאים והכניסן לדיר, ויצאו\u0004 תחילה \u0003ששה בפתח זה, ו\u0004לאחר מכן \u0003ארבעה בפתח זה,\u0004 בפתח אחר, \u0003וארבעה נשתיירו שם. אותם ארבעה\u0004 שנשתיירו, \u0003אם בפתח\u0004 שיצאו \u0003הששה,\u0004 אף הם \u0003יצאו\u0004 — \u0003נוטל אחד מהם\u0004 (האחרון) למעשר, \u0003והשאר,\u0004 הארבעה שיצאו בפתח השני — חייבים במעשר, ו\u0003מצטרפין לגורן אחר,\u0004 מפני שכשהחלו לצאת בפתח האחר כדי להתעשר — לא היה מנין ראוי, שהרי היו בדיר רק שמונה.","\u0003ואם לאו,\u0004 שלא יצאו הארבעה שנותרו בפתח שיצאו בו הששה, אלא שנשתיירו בדיר, או שיצאו בפתח השני — ה\u0003ששה\u0004 שיצאו תחילה \u0003פטורין,\u0004 שהרי כשיצאו היה בדיר מנין הראוי, \u0003וארבעה ארבעה\u0004 \u0003מצטרפין לגורן אחר,\u0004 מפני שכשהחלו הארבעה לצאת בפתח השני כדי להתעשר, כבר לא היו בדיר עשרה.","\u0003יצאו\u0004 תחילה \u0003ארבעה בפתח זה ו\u0004לאחר מכן \u0003ששה בפתח זה, ונשתיירו שם ארבעה, אם אותם ארבעה בפתח הששה יצאו\u0004 — \u0003נוטל מהם אחד\u0004 למעשר, \u0003והשאר,\u0004 הארבעה שיצאו ראשונים — \u0003פטורים,\u0004 שהרי יצאו כשהיה שם מנין הראוי. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שיצאו הארבעה שנותרו בפתח שיצאו בו הארבעה הראשונים, או שלא יצאו בכלל — ה\u0003ארבעה\u0004 שיצאו ראשונים \u0003ו\u0004ה\u0003ששה\u0004 שיצאו בפתח השני, \u0003פטורים,\u0004 שהרי יצאו בשעה שהיה בדיר מנין הראוי, \u0003ו\u0004ה\u0003ארבעה\u0004 שנותרו \u0003מצטרפין לגורן אחר,\u0004 מפני שבפתח שיצאו הם לא היו חלק ממנין עשרה.","\u0003יצאו\u0004 תחילה \u0003ארבעה בפתח זה, וארבעה בפתח זה, ונשתיירו שם ששה, אם אותן ששה יצאו בפתח אחד\u0004 — הצטרפו לארבעה שיצאו כבר באותו פתח, ו\u0003נוטל מהם אחד\u0004 למעשר. \u0003והשאר,\u0004 הארבעה שיצאו בפתח האחר — \u0003פטורים,\u0004 שהרי יצאו במנין הראוי, כשהיו ששה בדיר, שהיו ראויים להצטרף עמהם. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שלא יצאו הששה בעקבות הארבעה — \u0003ארבעה\u0004 הראשונים וארבעה האחרונים \u0003פטורים, וששה מצטרפין לגורן אחר.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בכל הדברים הללו, ש\u0003מנין הראוי פוטר? והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003רבא\u0004 דבר זה \u0003חדא זמנא\u0004 \u0005[פעם אחת]!\u0006 ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ודאי מנין הראוי אמרינן\u0004 \u0005[אומרים אנו]\u0006 שהוא פוטר, אבל \u0003ספק מנין הראוי,\u0004 וכגון שהחלו לצאת בשני פתחים, \u0003דחזי להכא ודחזי להכא\u0004 \u0005[ש\u0006הנותרים בפנים \u0005ראויים\u0006 לצאת \u0005לכאן וראויים לכאן],\u0006 ואולי לא יצאו בפתח זה — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שיתקיים במנויים כבר דין מנין הראוי, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם זה פוטר.","\u0003ואמר רבא: היו לו חמשה עשר טלאים,\u0004 והגיע זמן הגורן — \u0003לא יאמר: אברור עשרה\u0004 מהם \u0003ואכניסם לדיר ואטול מהם אחד\u0004 למעשר, \u0003והשאר\u0004 שלא היו בתוך הדיר יהיו \u0003פטורים,\u0004 מפני שכעת אין לי עשרה. \u0003אלא כונסן\u0004 כולם \u0003לדיר, ומוציא עשרה\u0004 מן הפתח \u0003ונוטל מהם אחד\u0004 (האחרון) למעשר, \u0003והשאר,\u0004 שהיו בתוך הדיר כשעישר, נתחייבו במעשר, וממתין שייוולדו לו טלאים נוספים, ו\u0003מצטרפין\u0004 עימם \u0003לגורן אחר.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003היו לו חמשה עשר טלאים\u0004 —"],["\u0003לא יאמר: אברור עשרה ואטול מהן אחד,\u0004 ובכך אצא ידי חובת המעשר בגורן זה, \u0003והשאר\u0004 יהיו \u0003פטורים\u0004 מלהתעשר. \u0003אלא כונסן\u0004 כולם \u0003לדיר, ומוציא עשרה ונוטל מהן אחד, והשאר,\u0004 שנותרו בדיר — \u0003מצטרפין ל\u0004התעשר ב\u0003גורן אחר.\u0004 ומקשים: כיצד אמר רבא שהשאר חייבים ומצטרפים לגורן אחר?","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 היו לו \u0003תשעה עשר טלאים, לא יאמר: אברור עשרה ואטול מהן אחד, והשאר פטורין. אלא כונסן לדיר, ומוציא עשרה ונוטל מהן אחד, והשאר פטורין\u0004 לגמרי!","\u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 \u0003רב הונא בר סחורה קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא בריגלא\u0004 \u0005[ב\u0006זמן דרשת \u0005הרגל]:\u0006 \u0003בדיר שיש לו שני פתחים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ויצאו תשעה בפתח זה ותשעה בפתח זה,\u0004 שהרי \u0003האיך חד\u0004 \u0005[אותו אחד]\u0006 שנותר \u0003חזי להכא ולהכא\u0004 \u0005[ראוי\u0006 היה כעשירי \u0005לכאן ולכאן],\u0006 כלומר, להשלים פתח זה או פתח זה לעשרה. וכך נפטרו התשעה שיצאו בכל אחד מן הפתחים, שהרי נפטרו במנין הראוי לעשרה.","ושואלים: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]\u0006 באופן אחר: \u0003כגון שמנה תשעה,\u0004 ונפטרו במנין הראוי לעשרה, \u0003וכי מטא עשרה\u0004 \u0005[וכאשר הגיע העשירי]\u0006 לא קרא לו \"עשירי\", אלא \u0003קרי \"חד\" מרישא\u0004 \u0005[קרא\u0006 לו \u0005\"אחד\" מההתחלה],\u0006 ולאחד עשר קרא \"שנים\", והמשיך למנותם, וקידש את האחרון לעשירי! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רבא: \u0003עשירי מאליו קדוש,\u0004 למרות שקרא לו בשם אחר. ונמצא שהתשעה האחרונים לא נפטרו, שהרי לא היה בהם מנין הראוי.","ועוד שואלים: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]\u0006 שמדובר \u0003בגורן\u0004 שיש בה רק פתח אחד, \u0003ומנאן\u0004 \u0005[ומנה אותם]\u0006 \u0003זוגות זוגות,\u0004 והטלה התשעה עשר הריהו מעשר ופוטר כולם! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רבא: \u0003עשירי למנין בהמות הוא קדוש,\u0004 ולפיכך אחד מן הטלאים שיצאו בזוג החמישי הריהו מעשר, וכך התשעה שנותרו לא נפטרו מן המעשר.","בעקבות דברים אלו \u0003אמר רב נחמן בר יצחק: זכאי אימיה\u0004 \u0005[זכאית אימו]\u0006 של \u0003רב הונא בר סחורה,\u0004 שילדה בן כמותו, \u0003דשני ליה שמעתא בריגלא כשמעתיה\u0004 \u0005[שתירץ לו\u0006 לרבא \u0005שמועה ב\u0006דרשת \u0005הרגל כשמועתו]\u0006 לפי דרכו של רבא עצמו, שאמר שמנין הראוי פוטר, ושעשירי קדוש מאליו.","היה מעביר את צאנו בפתח כדי לעשרם, ו\u0003יצאו שנים כאחת\u0004 — \u0003מונה אותם שנים שנים,\u0004 כאילו יצאו בזה אחר זה. ואם טעה ו\u0003מנאן אחד,\u0004 והמשיך במניינו — נמצא ש\u0003תשיעי ועשירי\u0004 שלפי מניינו \u0003מקולקלין.\u0004 שקרא לעשירי \"תשיעי\", ולאחד עשר קרא \"עשירי\".","טעה ו\u0003קרא לתשיעי \"עשירי\" ולעשירי \"תשיעי\", ולאחד עשר \"עשירי\"\u0004 — \u0003שלשתן מקודשין\u0004 במידה מסויימת, אך לכל אחד מהם דין שונה: \u0003התשיעי\u0004 אינו קרב ו\u0003נאכל\u0004 לבעליו \u0003במומו\u0004 (לאחר שנופל בו מום), \u0003והעשירי\u0004 — \u0003מעשר\u0004 ממש, שקרב במקדש, ונאכל על ידי הבעלים. \u0003ו\u0004ה\u0003אחד עשר\u0004 יש בו קדושה שהוא \u0003קרב שלמים,\u0004 שצריך לתת מהם חזה ושוק לכהנים. \u0003ועושה תמורה,\u0004 שאם אמר על בהמת חולין שתהא תמורתו — הרי היא מתקדשת, ומקריב אותה כקרבן שלמים, אלו \u0003דברי ר' מאיר.\u0004","\u0003אמר ר' יהודה:\u0004 והלוא אחד עשר זה שקראו \"עשירי\" הריהו תמורת מעשר. \u0003וכי יש תמורה עושה תמורה?\u0004 והלא אין מי שחולק על כך שאין תמורה עושה תמורה! \u0003אמרו משום\u0004 (בשם) \u0003ר' מאיר:\u0004 האחד עשר אינו נחשב תמורת מעשר, לפי ש\u0003אילו היה תמורה\u0004 — \u0003לא היה קרב\u0004 בעצמו, שאין תמורת מעשר קרבה. \u0003קרא לתשיעי \"עשירי\", ו\u0004גם \u0003לעשירי\u0004 קרא \u0003\"עשירי\", ו\u0004גם \u0003לאחד עשר\u0004 קרא \u0003\"עשירי\"\u0004 — \u0003אין אחד עשר מקודש. זה הכלל: כל שלא נעקר שם עשירי ממנו,\u0004 מן העשירי — \u0003אין אחד עשר מקודש.\u0004","\u0003אמר ר' יוחנן: מנאן\u0004 את הבהמות \u0003זוגות זוגות,\u0004 לזוג הראשון קרא \"אחד\", לזוג השני קרא \"שנים\" וכו', או שמנאם \u0003קינטרן קינטרן\u0004 (מאות מאות) — \u0003עשירי למנינו הוא קדוש.\u0004","ושואלים: \u0003\"למנינו\" מאי\u0004 \u0005[מהו],\u0006 כלומר, לאיזה מנין? \u0003רב מארי אמר:\u0004 העשירי \u0003למנין שלו הוא קדוש,\u0004 כלומר, כל אלו שקרא להם \"עשירי\" — כגון הזוג העשירי (הטלה התשעה עשר והטלה העשרים), או המאה העשירית. \u0003רב כהנא אמר:\u0004 העשירי \u0003למנין בהמות הוא קדוש,\u0004 ודוקא בהמה שיצאה עשירית הריהי קדושה.","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003יצאו שנים כאחת\u0004 — \u0003מונה אותן שנים שנים. מנאן אחד,\u0004 והמשיך למנות לפי טעותו — \u0003תשיעי ועשירי מקולקלין,\u0004 שקרא לעשירי \"תשיעי\", ולאחד עשר \"עשירי\", ודינם כפי שנתבאר במשנה, שהעשירי מעשר, והאחד עשר — שלמים.","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003למנין שלו הוא קדוש, משום הכי הוו\u0004 \u0005[משום כך נעשו]\u0006 \u0003תשיעי ועשירי מקולקלין\u0004 — שהרי יש חשיבות לדרך קריאתו, \u0003ולעשירי קא קרי ליה\u0004 \u0005[הוא קורא לו]\u0006 \u0003\"תשיעי\", ולאחד עשר\u0004 הוא קורא \u0003\"עשירי\". אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003למנין בהמות הוא קדוש,\u0004 ואין חשיבות למה שמנה בפיו, מדוע הם מקולקלים? הרי \u0003לתשיעי\u0004 נחשב כאילו \u0003\"תשיעי\" קא קרי ליה\u0004 \u0005[קורא לו],\u0006 \u0003ולעשירי\u0004 נחשב כאילו \u0003\"עשירי\" קא קרי ליה\u0004 \u0005[קורא הוא לו]!\u0006","ומשיבים לשיטת רב כהנא, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0005ר' יוחנן:\u0006 \u0003כי אמינא אנא\u0004 \u0005[כאשר אומר אני]\u0006 שהולכים לפי מנין הבהמות, הרי זה \u0003היכי דאיכוין לאפוקי\u0004 \u0005[במקום ש\u0006הוא עצמו \u0005התכוון להוציא]\u0006 אותם \u0003זוגות זוגות,\u0004 ולא טעה, שאז בטל דיבורו, והם מתקדשים לפי סדר יציאתם. אבל \u0003היכא דנפק ממילא\u0004 \u0005[במקום ש\u0006הם \u0005יוצאים מעצמם],\u0006 אך טעה במניינו — \u0003לא,\u0004 שכן יש ריבוי מיוחד בתורה, שהם מתקדשים גם לפי טעותו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: אם יצאו ו\u0003מנאן למפרע:\u0004 עשרה, תשעה, שמונה וכו' — \u0003עשירי שבמנין,\u0004 שקרא לו \"אחד\" \u0003הוא קדוש.\u0004 ואומרים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003למנין בהמות הוא קדוש\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 שהרי זה הטלה העשירי. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שגם \u0003למנין שלו הוא קדוש,\u0004 ויש חשיבות לדרך שקרא להם בפיו, הלא ל\u0003עשירי\u0004 הזה \u0003\"חד\" קרי ליה\u0004 \u0005[\"אחד\" הוא קורא לו]!\u0006","\u0003אמר רבא: הואיל ואיתיה במנינא פרסאה\u0004 \u0005[וישנו\u0006 הדבר \u0005במנין\u0006 של \u0005הפרסים],\u0006 \u0003דקרו לעשרה \"חד\"\u0004 \u0005[שהם קוראים לעשירי\u0006 בשפתם \u0005\"אחד\"],\u0006 ונמצא שבאופן זה אין סתירה בין מנין הבהמות למנין שלו."],["שנינו במשנתנו: \u0003קרא לתשיעי \"עשירי\", ולעשירי \"תשיעי\", ולאחד עשר \"עשירי\"\u0004 — שלושתם מקודשים, התשיעי נאכל במומו, והעשירי מעשר, ואחד עשר קרב שלמים. ובמקורה של הלכה זו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאם קרא לתשיעי \"עשירי\", ולעשירי \"תשיעי\", ולאחד עשר \"עשירי\", ששלשתן מקודשין?\u0004","\u0003תלמוד לומר: \"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי יהיה קדש\"\u0004 (ויקרא כז, לב), וייתור הלשון מלמד שקדושה חלה הן על זה שעבר עשירי והן על זה שקראו בפיו \"עשירי\". \u0003יכול שאני מרבה\u0004 שיקדשו \u0003אף שמיני ושנים עשר,\u0004 כשקרא להם בטעות \"עשירי\"?","\u0003אמרת\u0004 (אומר אתה): \u0003הואיל והוא\u0004 (העשירי) \u0003קדוש, וטעותו מתקדשת\u0004 (אם קרא לאחר \"עשירי\") יש ללמוד ממנו על טעותו: \u0003מה הוא\u0004 העשירי \u0003אינו מקודש אלא בסמוך\u0004 לו, כלומר, הוא עצמו — \u0003אף טעותו אינה מתקדשת אלא בסמוך\u0004 לו, לעשירי, כלומר, רק התשיעי והאחד עשר.","וביחס למה ששנינו שאם קרא גם לתשיעי וגם לאחד אשר \"עשירי\" — שניהם מקודשים, מתקשים, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא]: \u0003מה הוא מיוחד אף טעותו מיוחדת\u0004, ומדוע לא תחול הקדושה רק על אחד מהם?","\u0003תאני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אלעזר בן ר' שמעון היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בן ר' שמעון אומר: לעולם אין אחד עשר קדוש עד שישתוק ב\u0004יציאת ה\u0003תשיעי, ויקרא לעשירי\u0004 בטעות \u0003\"תשיעי\", ולאחד עשר\u0004 יטעה ויקרא \u0003\"עשירי\".\u0004 אבל אם כבר טעה פעם אחת, בתשיעי, וקרא לו \"עשירי\" — אין אחד עשר מקודש.","ומסבירים: טעמו של ר' אלעזר בר' שמעון, הוא מפני ש\u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה,\u0004 ש\u0003אמר: טעות מעשר,\u0004 כגון שקרא לתשיעי \"עשירי\" — \u0003תמורה הוי\u0004 \u0005[הוא],\u0006 דין תמורה יש לו, \u0003וסבר לה כאבוה\u0004 \u0005[וסבור כ\u0006דעת \u0005אביו]\u0006 ר' שמעון, ש\u0003אמר: אין\u0004 אדם \u0003מימר\u0004 (עושה תמורה) ו\u0003חוזר ומימר,\u0004 שאין קרבן עושה אלא תמורה אחת. ולכן, כשטעה בתשיעי, נחשב הדבר כאילו המיר בו את העשירי, ולפיכך כשטעה אחר כך גם באחד עשר — לא תחול עליו קדושה.","\u0003אמר רבא: יצאו שנים\u0004 יחד דרך פתח הדיר \u0003בתשיעי,\u0004 ו\u0003קראן \"תשיעי\"\u0004 — הרי יש כאן \u0003עשירי\u0004 (מעשר) \u0003וחולין\u0004 שהם \u0003מעורבין זה בזה,\u0004 כי \u0003עשירי מאליו קדוש,\u0004 למרות שקראו בשם תשיעי, וזה שיצא \u0003תשיעי\u0004 הריהו חולין גמורים, שהרי גם יצא תשיעי, וגם \u0003תשיעי קא קרי ליה\u0004 \u0005[הוא קורא לו].\u0006 והואיל ולא ניתן לזהותם — אי אפשר להקריב אף אחד מהם, שמא הוא חולין, וירעו שניהם עד שיפול בהם מום וייאכלו.","ואם יצאו שנים בתשיעי ו\u0003קראן \"עשירי\"\u0004 — הרי \u0003עשירי ותשיעי\u0004 שקראו \"עשירי\" \u0003מעורבין זה בזה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"עשירי\" קא קרי להו לתרוייהו\u0004 \u0005[קורא להם לשניהם].\u0006 ואחד מתקדש כמעשר, והשני הוא תשיעי שקראו \"עשירי\", שנאכל במומו לבעלים. ומספק אסורים שניהם בהקרבה, וירעו עד שיפול בם מום וייאכלו.","ואם \u0003יצאו שנים בעשירי וקראן \"עשירי\"\u0004 — \u0003עשירי ואחד עשר\u0004 שקראו \"עשירי\" \u0003מעורבין זה בזה\u0004 (ודינם יבואר בהמשך). ואם יצאו שנים בעשירי ו\u0003קראן \"אחד עשר\"\u0004 — \u0003עשירי וחולין מעורבין זה בזה.\u0004","ושואלים: \u0003הא תו\u0004 \u0005[זה עוד],\u0006 כלומר, כשיצאו שנים בעשירי וקראם \"עשירי\", או קראם \"אחד עשר\", \u0003למה לי\u0004 לאומרו? \u0003היינו הך\u0004 \u0005[הרי הוא זה],\u0006 כלומר, הרי זה דומה לדין הראשון, שיצאו שנים בתשיעי וקראם \"עשירי\" או קראם \"תשיעי\"! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 שב\u0003כל\u0004 מקרה שיצאו ב\u0003בת אחת תרווייהו קא קדשי\u0004 \u0005[שניהם מתקדשים],\u0006 וגם האחד עשר, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא נעקר שם עשירי הימנו\u0004 (ממנו), מן העשירי. ואין זה בכלל מה ששנינו במשנתנו: כל שלא נעקר שם עשירי ממנו אין אחד עשר מקודש.","וכיוצא בזה מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב כהנא וקאמר ליה להא שמעתא\u0004 \u0005[ואומר את השמועה הזו]\u0006 שאמר רבא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: והלא\u0004 כשיצאו שנים בעשירי וקראם \"עשירי\", \u0003לא נעקר שם \"עשירי\" הימנו, ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003זה הכלל, כל זמן שלא נעקר שם \"עשירי\" הימנו\u0004 — \u0003אין אחד עשר מקודש!\u0004 השיב לו: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005],\u0006 כשיצאו \u0003בזה אחר זה, אבל\u0004 אם יצאו שנים \u0003בבת אחת,\u0004 וקראם \"עשירי\" — \u0003תרוייהו קא קדשי\u0004 \u0005[שניהם מתקדשים].\u0006","ומקשים: כשיצאו \u0003בזה אחר זה\u0004 — הלא \u0003בהדיא קתני לה\u0004 \u0005[במפורש הוא שונה אותה]\u0006 במשנה בתחילה: \u0003קרא לתשיעי \"עשירי\", ולעשירי \"עשירי\", ולאחד עשר \"עשירי\"\u0004 — \u0003אין אחד עשר מקודש,\u0004 ואם כן \u0003\"זה הכלל\"\u0004 שהוסיפה המשנה \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 הוא בא, \u0003לאו לאיתויי\u0004 \u0005[האם לא להביא]\u0006 מקרה שיצאו שנים \u0003בבת אחת\u0004 בעשירי, וקראם \"עשירי\", וללמדנו שלא יקדש האחד עשר, ושלא כדברי רבא?","ומשיבים: \u0003לא, לאיתויי\u0004 \u0005[להביא]\u0006 מקרה שיצאו בזה אחר זה, ו\u0003יצא עשירי ולא דבר\u0004 כלל, ואחריו יצא אחד עשר וקראו \"עשירי\", ללמד שגם במקרה זה אין אחד עשר מקודש, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא נעקר שם עשירי הימנו,\u0004 מן העשירי.","אבל כשיצאו שניהם כאחד — שניהם מתקדשים, \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 \u0003הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנויה]:\u0006 \u0003יצאו שנים בעשירי, ולא קדם אחד מהן את חבירו, וקראן\u0004 לשניהם \u0003\"עשירי\",\u0004 הרי \u0003עשירי ואחד עשר\u0004 שנתקדש \u0003מעורבין זה בזה\u0004 — יש לתמוה על כך: מדוע אחד עשר מקודש? \u0003והלא לא נעקר שם עשירי הימנו\u0004 מן העשירי! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003כל\u0004 שיצאו \u0003בבת אחת\u0004 וקראם \"עשירי\", \u0003תרוייהו קא קדשי\u0004 \u0005[שניהם מתקדשים],\u0006 וכרבא?","ודוחים: \u0003אי משום הא לא איריא\u0004 \u0005[אם משום זו אין להוכיח],\u0006 שכן יש לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בברייתא \u0005זו, במה אנו עוסקים]\u0006 — \u0003דקדים חד מינייהו ואפיק לרישיה\u0004 \u0005[שקדם אחד מהם והוציא את ראשו]\u0006 לצאת בעשירי, \u0003וקרייה\u0004 \u0005[וקרא אותו]\u0006 \u0003\"אחד עשר\", והדר איערוב ונפוק בהדדי\u0004 \u0005[ואחר כך התערבו ויצאו ביחד],\u0006 \u0003וקרינהו\u0004 \u0005[וקרא אותם]\u0006 \u0003\"עשירי\".\u0004 ודוקא במקרה זה קדוש גם האחד עשר כשקרא את שניהם \"עשירי\", \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003נעקר שם עשירי הימנו\u0004 מן העשירי, כשקראו מתחילה \"אחד עשר\".","ותוהים: וכיצד יכול אתה לפרש שמדובר כשכבר הוציא אחד מהם את ראשו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לא קדם\u0004 אחד מהן את חבירו\" \u0003קתני\u0004 \u0005[הוא שונה]\u0006 בברייתא! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא קדם\"\u0004 — \u0003דהדר איערוב\u0004 \u0005[שחזר ונתערב].\u0006","ומקשים: \u0003וכמאן\u0004 \u0005[וכדעת מי]\u0006 העמדת את הברייתא? ש\u0003לא כ\u0004שיטת \u0003רבי, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003רבי\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 שקריאת שם \u0003\"אחד עשר\"\u0004 לעשירי \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003עקירה!\u0004","ודוחים: יש להבין דבר זה \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003רבי,\u0004 שכן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר רבי\u0004 שקריאת שם \"אחד עשר\" אינה מהוה עקירה, הרי זה \u0003היכא דאית ליה\u0004 \u0005[במקום שיש לו]\u0006 \u0003בהמות טובא\u0004 \u0005[הרבה]\u0006 לעשר, \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 כשאמר \"אחד עשר\" על הבהמה העשירית — \u0003חד עישורא קאמר\u0004 \u0005[עישור אחד הוא אומר],\u0006 שבבהמה זו, העשירית, גמר לעשר פעם אחת. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003דלית ליה בהמות טפי\u0004 \u0005[שאין לו בהמות יותר],\u0006 ובמקרה זה גם רבי סבור שקריאת שם \"אחד עשר\" לעשירי נחשבת לעקירה.","ומבררים: \u0003מאי\u0004 \u0005[מהי]\u0006 שיטת \u0003רבי\u0004 שהזכרנו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קרא לעשירי \"אחד עשר\", ולאחד עשר\u0004 קרא \u0003\"עשירי\"\u0004 — \u0003אין אחד עשר קדוש,\u0004 והוא חולין, אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר: אחד עשר קדוש\u0004 בקדושתו, וקרב כשלמים. \u0003כלל אמר רבי: כל זמן שלא נעקר שם עשירי הימנו\u0004 על ידי קריאתו בשם אחר, \u0003אין אחד עשר קדוש.\u0004 ותמהים על דברי רבי: והלא כשקרא לעשירי \"אחד עשר\" נעקר שמו ממנו! \u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003בהמות טובא\u0004 \u0005[הרבה],\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים],\u0006 כשאמר \"אחד עשר\" — \u0003חד עישורא קאמר\u0004 \u0005[עישור אחד אמר],\u0006 ולא נעקר שמו ממנו.","ושבים לדין שכבר הוזכר בעמוד זה. \u0003יצאו שנים בעשירי\u0004 וקראם \"עשירי\", ויש כאן איפוא מעשר המעורב באחד עשר שקראו \"עשירי\", שדינו לקרב שלמים, מה יעשה בהם? \u0003תנא חדא\u0004 \u0005[שנה\u0006 תנא \u0005אחד]:\u0006 \u0003ירעו\u0004 שניהם עד שיפול בהם מום ויאכלום, \u0003ותנא חדא\u0004 \u0005[ושנה\u0006 תנא \u0005אחד]:\u0006 \u0003יקריבו\u0004 את שניהם, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003ימותו\u0004 שניהם.","ומסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא דתנא\u0004 \u0005[זה ששנה]\u0006 \u0003ירעו\u0004 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אין מביאין קדשים לבית הפסול,\u0004 ואם נאמר ששניהם קרבים — יש לנהוג בשניהם לחומרה, וכדין שלמים, ולתת את החזה והשוק לכהנים. והואיל וכהנים אינם מרובים — שמא לא יספיקו לאכול את חלקם בזמן, והנותר ייפסל ויישרף."],["\u0003והא דתאני\u0004 \u0005[וזה ששנה]:\u0006 \u0003יקריבו\u0004 שניהם כקרבן שלמים — שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: מביאין קדשים לבית הפסול,\u0004 כלומר, מותר להקריב קדשים, למרות שיש חשש שמא לא יספיקו לאוכלם וייפסלו.","\u0003והא דתני\u0004 \u0005[וזה ששנה]\u0006 \u0003ימותו\u0004 שניהם — שיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: טעות מעשר,\u0004 כגון אחד עשר שקראו \"עשירי\" — \u0003תמורה הויא\u0004 \u0005[היא],\u0006 ו\u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה: תמורת מעשר מתה\u0004 דינה למיתה, ומספק איזהו האחד עשר — ימותו שניהם.","ותוהים: \u0003וקסבר\u0004 \u0005[ו\u0006כי \u0005סבור]\u0006 \u0003ר' יהודה תמורת מעשר מתה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005],\u0006 \u0003אמרו משום\u0004 (בשם) \u0003ר' מאיר\u0004 (כתשובה לדברי ר' יהודה): \u0003אילו\u0004 האחד עשר שקראו \"עשירי\" \u0003היה תמורה\u0004 של מעשר — \u0003לא היה קרב, מכלל\u0004 הדברים אתה למד ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 ש\u0003קרב,\u0004 למרות שלדעתו הוא תמורת מעשר!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003ר' מאיר למאי דסבירא ליה קאמר\u0004 \u0005[ל\u0006פי \u0005מה ש\u0006הוא עצמו \u0005סבור הוא אומר],\u0006 לשיטתו, שאין האחד עשר נחשב תמורת מעשר, מפני שאם כן — לא היה קרב. אבל אין ללמוד מכאן על דעת ר' יהודה, ולדעתו דינו ככל תמורת מעשר שמתה — \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין בין\u0004 קדושת \u0003אחד עשר\u0004 שקראו \"עשירי\" \u0003ל\u0004קדושת קרבן \u0003שלמים\u0004 רגיל, \u0003אלא שזה\u0004 (קרבן שלמים) \u0003עושה קדושה ליקרב,\u0004 שהוא עושה תמורה ותמורתו קריבה, \u0003וזה\u0004 האחד עשר \u0003אין עושה קדושה ליקרב,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ונדייק מכאן: לעשות \u0003קדוש ליקרב הוא דלא עביד\u0004 \u0005[שאין הוא עושה]\u0006 האחד עשר, \u0003הא איהו גופיה קריב\u0004 \u0005[אבל הוא עצמו קרב]!\u0006","\u0003ועוד\u0004 ראיה שכך דעתו של ר' יהודה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בסיפרא, מדרש ההלכה על ספר ויקרא: \"ואם זבח שלמים קרבנו \u0003אם מן הבקר\"\u0004 (ויקרא ג, א) — הרי זה בא \u0003לרבות אחד עשר\u0004 שקראו \"עשירי\", שיהיה אף הוא מוקרב \u0003לשלמים.\u0004","\u0003יכול שאני מרבה אף\u0004 את \u0003התשיעי,\u0004 שקראו \"עשירי\", שיקרב לשלמים? \u0003אמרת\u0004 (אומר אתה): \u0003וכי הקדש לפניו מקדש או לאחריו מקדש?\u0004 כלומר, האם לפני שהוא עצמו התקדש יכול הוא לקדש אחרים כתמורתו, או דוקא לאחר שהוא עצמו התקדש? \u0003הוי אומר\u0004 — \u0003לאחריו מקדש,\u0004 ולכן דוקא האחד עשר שנתקדש לאחר שכבר יצא העשירי ונתקדש — קרב שלמים מכח העשירי. אבל התשיעי, שנתקדש לפניו — אינו קרב שלמים.","שיטת \u0003סתם סיפרא מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה\u0004 היא, \u0003וקתני\u0004 \u0005[ו\u0006הרי \u0005הוא שונה]\u0006 שם: \u0003\"מן הבקר\"\u0004 — \u0003לרבות אחד עשר לשלמים,\u0004 ואינו סבור שהוא הולך למיתה. ואם כן, הברייתא ששנינו בה שעשירי ואחד עשר שנתערבו ימותו — לא ניתן להעמידה לשיטתו! אלא תרגמה \u0005[פירש אותה],\u0006 את הברייתא, \u0003ר' שמעון בר' אבא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: במעשר בזמן הזה,\u0004 שחרב המקדש, \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ו\u0004לדעת התנא ילכו למיתה \u0003משום\u0004 חשש \u0003תקלה,\u0004 שמא יגזוז אותם או יעבוד בהם, או שמא יאכלם בלא מום.","","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע מדובר דוקא במקרה של \u0003תרי\u0004 \u0005[שנים]\u0006 שיצאו והתערבו? \u0003אפילו חד נמי\u0004 \u0005[\u0006ב\u0005אחד גם כן]\u0006 שייך דין זה, בכל מעשר בהמה! ומשיבים: בלשון \u0003\"לא מיבעיא\" קאמר\u0004 \u0005[\"לא נצרכה\" הוא אומר],\u0006 \u0003לא מיבעיא חד דלית ליה פסידא\u0004 \u0005[לא נצרכה\u0006 לומר ב\u0005אחד, שאין לו הפסד\u0006 גדול\u0005]\u0006 אם ימות, אמרו חכמים שילך למיתה. \u0003אבל תרי\u0004 \u0005[שנים],\u0006 \u0003כיון דנפישי פסידא\u0004 \u0005[שמרובה ההפסד],\u0006 הייתי אומר: \u0003לישהינהו\u0004 \u0005[שישהה אותם]\u0006 \u0003עד דניפול בהו מומא\u0004 \u0005[שיפול בהם מום]\u0006 \u0003וליכלינהו\u0004 \u0005[ושיאכל אותם],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין עושים כן.","שנינו במשנה שהקורא לתשיעי \"עשירי\" — הריהו קדוש ליאכל רק לאחר שיפול בו מום, והקורא לאחד עשר \"עשירי\" — קדוש וקרב כקרבן שלמים. ובענין זה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים: \u0003האומר לשלוחו \"צא ועשר עלי\u0004 את בהמותי\" — \u0003רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר:\u0004 אם \u0003קרא\u0004 השליח \u0003לתשיעי \"עשירי\",\u0004 ובכך גרם לו להיאסר בשחיטה עד שיפול בו מום — בכל זאת הריהו \u0003קדוש,\u0004 מפני שאין הבעלים מקפידים על טעות זו, שאינה גורמת לו הפסד. \u0003ו\u0004אולם אם קרא \u0003לאחד עשר \"עשירי\"\u0004 — \u0003אינו קדוש\u0004 בקדושת אחד עשר, ליקרב שלמים, מפני שהבעלים אינו מוכן שיחסר ממונו, שהרי צריך ליתן חזה ושוק לכהן, ולא עשאו שליח לכך. \u0003ורב פפא אמר: אפילו קרא לתשיעי \"עשירי\"\u0004 — \u0003אינו קדוש\u0004 כלל, שהבעלים \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 לשליח: \u0003לתקוני שדרתיך ולא לעוותי\u0004 \u0005[לתקן שלחתי אותך ולא לקלקל],\u0006 והרי צריך אני להמתין מלשוחטו, ואסור לי לגוזזו ולעבוד בו, ולענין זה לא היית שלוחי.","ושואלים: \u0003ומאי שנא מהא דתנן\u0004 \u0005[ובמה שונה\u0006 דבר זה \u0005מזו ששנינו]\u0006 במשנה: \u0003האומר לשלוחו \"צא ותרום\u0004 תבואה מתרומתי\", ולא פירש לו כמה יתרום — \u0003תורם כדעת בעל הבית,\u0004","\u0003אם אינו יודע דעתו של בעל הבית\u0004 — \u0003תורם ב\u0004עין \u0003בינונית,\u0004 שהיא \u0003אחד מחמשים\u0004 מן התבואה, אם \u0003פיחת עשרה או הוסיף עשרה,\u0004 שתרם אחד מארבעים או אחד משישים — בכל זאת \u0003תרומתו תרומה?\u0004 והרי יכול בעל הבית לומר לו ששלחו לתקן ולא לקלקל!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דאיכא דתרים\u0004 \u0005[שיש\u0006 מי \u0005שתורם]\u0006 \u0003בעין יפה, ואיכא דתרים\u0004 \u0005[ויש שתורם]\u0006 \u0003בעין רעה, אמר\u0004 \u0005[אומר]\u0006 לו השליח: \u0003להכי אמדתיך\u0004 \u0005[לכך אמדתי אותך],\u0006 שאתה בעל עין יפה או עין רעה. אבל \u0003הכא טעותא\u0004 \u0005[כאן טעות]\u0006 \u0003היא,\u0004 ובמקרה זה \u0003אמר\u0004 \u0005[אומר]\u0006 בעל הבית לשליח: \u0003לא איבעי לך למיטעי\u0004 \u0005[לא היה לך לטעות]\u0006 ולקלקל בענין זה.",""]]};
